    :root {
      --paper: #FBFAF7;
      --paper-warm: #F6F2EA;
      --ink: #1A1A1A;
      --ink-sub: #5C5C5C;
      --primary: #2C5F7F;
      --primary-deep: #1F4D6B;
      --gold: #C9A96E;
      --gold-soft: #EDE3CF;
      --line: #E8E4DC;
      --line-soft: #F0EDE5;
      --warn: #A85D5D;
      --warn-soft: #F4E9E5;
      --serif: "Noto Serif JP", "Yu Mincho", "游明朝", "Hiragino Mincho ProN", serif;
      --sans: "Noto Sans JP", "Yu Gothic", "游ゴシック", "Hiragino Sans", sans-serif;
      --num-data: "Inter", "Helvetica Neue", -apple-system, BlinkMacSystemFont, Arial, sans-serif;
      --num-deco: "Cormorant Garamond", "Noto Serif JP", serif;
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    section[id] { scroll-margin-top: 80px; }
    @media (max-width: 768px) { section[id] { scroll-margin-top: 70px; } }
    body {
      margin: 0;
      font-family: var(--sans);
      font-weight: 400;
      color: var(--ink);
      background: var(--paper);
      line-height: 1.95;
      letter-spacing: 0.04em;
      font-size: 16px;
      overflow-wrap: break-word;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }
    @media (max-width: 768px) {
      body { font-size: 15px; line-height: 1.9; letter-spacing: 0.03em; }
    }
    a { color: inherit; text-decoration: none; }
    p { margin: 0 0 1.4em; }
    p:last-child { margin-bottom: 0; }

    /* Japanese line-break tuning */
    h1, h2, h3, h4,
    .section-title, .section-lead, .chapter-head,
    .card, .point-card, .price-card, .flow-card, .contact-card,
    .hero-card, .sample-card, .sample-card--soon,
    .compliance-card, .report-card, .report-cover,
    .payment-note, .pricing-note, .price-note,
    .migration-pricing__card, .migration-total__notes,
    .vision-tool__note, .consult-flow__note, .line-contact-card,
    .cta-btn, .home-shortcut, .side-flow__label, .side-flow__caption,
    .faq-q, .faq-a, .body-text, .report-hero__lead,
    .report-cover__title, .report-panel, .report-flow__item,
    .impression-feature, .guide-card, .plan, .plan__note,
    .price-summary, .comparison-row, .migration-card,
    .compliance-pricing__card, .audit-box, .check-card,
    .medical-support__content, .medical-support__points,
    .medical-support__note, .medical-support__status,
    .medical-support__cta {
      line-break: strict;
      overflow-wrap: break-word;
      word-break: normal;
    }
    h1, h2, h3, h4,
    .section-title, .section-lead,
    .card h3, .point-card h3, .sample-card h3, .report-card h3,
    .payment-note strong, .cta-btn, .faq-q,
    .report-cover__title, .report-hero h1,
    .price-summary strong, .plan h3 {
      text-wrap: balance;
    }
    p, li, dd, td, .section-lead, .price-note, .payment-note p,
    .sample-card p, .report-card p, .faq-a, .body-text,
    .report-hero__lead, .plan__note, .compliance-note,
    .audit-box__note, .guide-card p, .impression-feature p,
    .medical-support__content p, .medical-support__points li {
      text-wrap: pretty;
    }
    @supports (word-break: auto-phrase) {
      h1, h2, h3, h4, p, li, dd, td,
      .section-title, .section-lead, .cta-btn,
      .card, .point-card, .price-card, .flow-card, .contact-card,
      .sample-card, .report-card, .payment-note, .faq-q, .faq-a,
      .price-note, .plan__note, .body-text {
        word-break: auto-phrase;
      }
    }
    .phrase-nowrap {
      display: inline-block;
      white-space: nowrap;
    }
    @media (max-width: 768px) {
      .section-lead, .price-note, .pricing-note, .payment-note p,
      .faq-a, .report-hero__lead, .body-text, .plan__note,
      .sample-card p, .report-card p, .guide-card p {
        letter-spacing: 0.01em;
      }
    }

    .wrap { width: min(1080px, 92%); margin: 0 auto; }
    .topbar .wrap { width: min(1240px, 94%); }
    .narrow { width: min(680px, 92%); margin: 0 auto; }
    .mid { width: min(820px, 92%); margin: 0 auto; }
    section { padding: 96px 0; }
    @media (max-width: 768px) { section { padding: 56px 0; } }

    .topbar {
      position: sticky; top: 0; z-index: 50;
      background: rgba(251, 250, 247, 0.94);
      backdrop-filter: saturate(180%) blur(12px);
      -webkit-backdrop-filter: saturate(180%) blur(12px);
      border-bottom: 1px solid var(--line);
    }
    .nav { height: 64px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
    .brand {
      display: inline-flex; align-items: center; gap: 12px;
      font-family: var(--serif); font-weight: 500; font-size: 13px;
      color: var(--ink); letter-spacing: 0.05em; line-height: 1.35;
      flex: 0 0 auto;
    }
    .brand-logo {
      display: block;
      width: 148px;
      height: 52px;
      object-fit: contain;
      object-position: left center;
      mix-blend-mode: multiply;
    }
    .brand-copy {
      display: block;
      max-width: 220px;
      word-break: keep-all;
    }
    .brand-copy .en {
      display: block; font-family: var(--num-deco); font-weight: 400;
      font-size: 9px; color: var(--gold); letter-spacing: 0.2em;
      margin-bottom: 1px; text-transform: uppercase;
    }
    .brand-copy__break { display: none; }
    .navlinks {
      display: flex;
      gap: 6px;
      align-items: center;
      flex: 0 0 auto;
      padding: 6px;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.62);
      box-shadow: 0 14px 34px rgba(15, 23, 42, 0.05);
      font-size: 12px;
      color: var(--ink-sub);
      white-space: nowrap;
    }
    .navlinks a {
      display: inline-flex;
      align-items: center;
      min-height: 34px;
      padding: 0 13px;
      border-radius: 999px;
      white-space: nowrap;
      word-break: keep-all;
      letter-spacing: 0.04em;
      transition: color 0.2s ease, background 0.2s ease;
    }
    .navlinks a:hover { color: var(--primary); background: rgba(31, 77, 107, 0.06); }
    .nav-cta {
      min-height: 42px;
      padding: 0 20px !important;
      margin-left: 4px;
      background: var(--primary-deep);
      color: var(--paper);
      border-radius: 999px;
      font-size: 13px;
      letter-spacing: 0.06em;
      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.20);
      transition: background 0.25s ease, transform 0.25s ease;
    }
    .nav-cta:hover { background: var(--primary); color: var(--paper); transform: translateY(-1px); }
    @media (max-width: 1120px) { .navlinks { display: none; } }
    @media (max-width: 768px) {
      .nav { height: 66px; }
      .brand {
        width: 100%;
        gap: 10px;
        font-size: 13px;
        line-height: 1.42;
        letter-spacing: 0.04em;
      }
      .brand-logo {
        width: 128px;
        height: 56px;
        flex: 0 0 auto;
      }
      .brand-copy {
        display: block;
        max-width: calc(100vw - 176px);
        word-break: normal;
      }
      .brand-copy .en {
        font-size: 8px;
        letter-spacing: 0.18em;
        margin-bottom: 2px;
      }
      .brand-copy__break { display: block; }
    }

    .side-flow {
      position: fixed;
      right: 14px;
      top: 50%;
      transform: translateY(-50%);
      z-index: 60;
      display: grid;
      gap: 8px;
      width: 112px;
      pointer-events: none;
    }
    .side-flow__item {
      pointer-events: auto;
      display: grid;
      place-items: center;
      gap: 5px;
      min-height: 94px;
      padding: 12px 10px 11px;
      background: rgba(251, 250, 247, 0.88);
      border: 1px solid rgba(44, 95, 127, 0.18);
      box-shadow: 0 16px 36px rgba(15, 23, 42, 0.11);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      color: var(--primary-deep);
      text-align: center;
      transition: transform 0.22s ease, background 0.22s ease, border-color 0.22s ease;
    }
    .side-flow__item:hover {
      transform: translateX(-4px);
      background: #fff;
      border-color: rgba(44, 95, 127, 0.38);
    }
    .side-flow__item svg {
      width: 24px;
      height: 24px;
      stroke: currentColor;
    }
    .side-flow__step {
      font-family: var(--num-data);
      font-size: 10px;
      line-height: 1;
      color: var(--gold);
      letter-spacing: 0.12em;
    }
    .side-flow__label {
      display: block;
      font-family: var(--serif);
      font-size: 14px;
      line-height: 1.35;
      letter-spacing: 0.08em;
      word-break: keep-all;
    }
    .side-flow__caption {
      display: block;
      margin-top: -2px;
      font-size: 10px;
      line-height: 1.35;
      color: var(--ink-sub);
      letter-spacing: 0.04em;
      word-break: keep-all;
    }
    .side-flow__item--line {
      background: rgba(44, 95, 127, 0.94);
      color: #fff;
      border-color: rgba(44, 95, 127, 0.72);
    }
    .side-flow__item--line .side-flow__step { color: rgba(255,255,255,.72); }
    .side-flow__item--line .side-flow__caption { color: rgba(255,255,255,.78); }
    .side-flow__item--line:hover { background: var(--primary-deep); }
    @media (max-width: 1180px) {
      .side-flow { right: 6px; width: 82px; }
      .side-flow__item { min-height: 78px; padding: 9px 6px 8px; }
      .side-flow__item svg { width: 20px; height: 20px; }
      .side-flow__label { font-size: 12px; }
      .side-flow__caption { display: none; }
    }
    @media (max-width: 900px) {
      body { padding-bottom: 74px; }
      .side-flow {
        left: 10px;
        right: 10px;
        bottom: 10px;
        top: auto;
        width: auto;
        transform: none;
        grid-template-columns: repeat(4, 1fr);
        gap: 6px;
      }
      .side-flow__item {
        min-height: 58px;
        padding: 8px 6px 7px;
        border-radius: 18px;
      }
      .side-flow__item:hover { transform: translateY(-2px); }
      .side-flow__item svg { width: 20px; height: 20px; }
      .side-flow__step { display: none; }
      .side-flow__label { font-family: var(--sans); font-size: 10px; line-height: 1.22; }
      .side-flow__caption { display: block; margin-top: 0; font-size: 8px; line-height: 1.2; }
    }

    .chapter-num {
      font-family: var(--num-deco); font-weight: 400; font-size: 13px;
      color: var(--gold); letter-spacing: 0.3em; text-transform: uppercase;
      margin-bottom: 12px; display: block;
    }

    h1, h2, h3, h4 {
      font-family: var(--serif); font-weight: 500;
      letter-spacing: 0.04em; color: var(--ink); line-height: 1.55;
    }
    h1 { font-size: clamp(28px, 4vw, 46px); line-height: 1.5; margin: 0 0 24px; }
    h2 { font-size: clamp(24px, 3vw, 34px); line-height: 1.55; margin: 0 0 20px; }
    h3 { font-size: 19px; line-height: 1.7; margin: 0 0 12px; }
    h4 { font-size: 16px; line-height: 1.7; margin: 0 0 10px; font-family: var(--sans); font-weight: 700; }

    .section-title { text-align: center; margin: 0 0 16px; }
    .section-lead {
      text-align: center; color: var(--ink-sub); font-size: 15px;
      max-width: 700px; margin: 0 auto 56px; line-height: 2.0;
    }
    .chapter-head { text-align: center; margin-bottom: 56px; }
    .chapter-head h2 { margin: 0 auto; max-width: 800px; }

    /* Number/data styling */
    .yen-suffix {
      font-family: var(--sans); font-weight: 500; font-size: 0.5em;
      letter-spacing: 0.04em; margin-left: 4px; color: var(--ink-sub);
    }

    /* Hero */
    .hero { padding: 100px 0 80px; background: var(--paper); position: relative; }
    .hero-inner { text-align: center; }
    .hero-showcase {
      max-width: 920px; margin: 0 auto 40px;
      border-radius: 4px; overflow: hidden;
      box-shadow:
        0 26px 50px rgba(40, 28, 18, 0.18),
        0 8px 16px rgba(40, 28, 18, 0.10);
      position: relative;
      aspect-ratio: 3 / 2;
      background: var(--paper-warm);
    }
    .hero-showcase picture { display: block; }
    .hero-showcase img {
      display: block; width: 100%; height: auto;
    }
    .hero-showcase__slide {
      position: absolute;
      inset: 0;
      opacity: 0;
      transform: scale(1.025);
      transition: opacity 1.2s ease, transform 1.8s ease;
    }
    .hero-showcase__slide:first-child,
    .hero-showcase__slide.is-active {
      opacity: 1;
      transform: scale(1);
    }
    .hero-showcase__slide picture,
    .hero-showcase__slide img,
    .hero-showcase__slide video {
      width: 100%;
      height: 100%;
    }
    .hero-showcase__slide img,
    .hero-showcase__slide video {
      object-fit: cover;
    }
    @keyframes heroPhotoCycle {
      0%, 28% {
        opacity: 1;
        transform: scale(1);
      }
      36%, 92% {
        opacity: 0;
        transform: scale(1.015);
      }
      100% {
        opacity: 1;
        transform: scale(1);
      }
    }
    @media (prefers-reduced-motion: reduce) {
      .hero-showcase__slide {
        animation: none;
      }
      .hero-showcase__slide:not(:first-child) {
        opacity: 0;
      }
    }
    @media (max-width: 768px) {
      .hero-showcase { margin-bottom: 28px; }
    }
    .hero h1 {
      font-size: clamp(26px, 3.6vw, 42px); line-height: 1.55;
      margin: 0 0 28px; font-weight: 500;
    }
    .hero-punch {
      margin: 0 auto 18px;
      font-family: var(--font-jp-serif);
      font-size: clamp(25px, 4.1vw, 48px);
      line-height: 1.45;
      color: var(--ink);
      letter-spacing: 0.03em;
    }
    .hero .divider { width: 40px; height: 1px; background: var(--gold); margin: 0 auto 28px; }
    .hero-meta {
      display: flex; justify-content: center; gap: 24px; margin-bottom: 32px;
      font-family: var(--num-deco); font-size: 12px; color: var(--gold);
      letter-spacing: 0.25em; text-transform: uppercase; flex-wrap: wrap;
    }
    .hero-cards {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
      max-width: 760px; margin: 40px auto 36px;
    }
    .hero-card {
      background: var(--paper-warm); border: 1px solid var(--line);
      padding: 28px 16px 24px; text-align: center;
    }
    .hero-card .label {
      font-family: var(--sans); font-size: 12px; color: var(--ink-sub);
      letter-spacing: 0.15em; margin-bottom: 12px; font-weight: 500;
    }
    .hero-card .value {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: clamp(26px, 3.4vw, 36px);
      color: var(--primary); line-height: 1.0; letter-spacing: -0.01em;
    }
    .hero-card .value .yen-suffix { font-size: 0.55em; color: var(--primary); }
    .hero-card .sub { font-size: 11px; color: var(--ink-sub); margin-top: 10px; letter-spacing: 0.05em; }
    .hero-incl {
      font-size: 14px; color: var(--ink-sub); max-width: 600px;
      margin: 0 auto 36px; line-height: 1.95;
    }
    /* Hero — two-path pricing */
    .hero-paths-heading {
      font-family: var(--serif); font-weight: 500;
      font-size: clamp(13px, 1.6vw, 15px); letter-spacing: 0.18em;
      color: var(--ink-sub);
      text-align: center; margin: 32px 0 18px;
    }
    .hero-paths {
      display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
      max-width: 780px; margin: 0 auto 28px;
    }
    .hero-path {
      background: var(--paper-warm); border: 1px solid var(--line);
      padding: 28px 24px 26px; text-align: center;
      border-radius: 2px; position: relative;
      overflow: hidden;
    }
    .hero-path__photo {
      margin: -28px -24px 22px;
      aspect-ratio: 4 / 3;
      overflow: hidden;
      background: var(--line-soft);
    }
    .hero-path__photo img {
      display: block; width: 100%; height: 100%;
      object-fit: cover;
      transition: transform 0.5s ease;
    }
    a.hero-path:hover .hero-path__photo img {
      transform: scale(1.03);
    }
    a.hero-path {
      text-decoration: none; color: inherit;
      display: flex; flex-direction: column;
      cursor: pointer;
      transition: border-color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
    }
    a.hero-path:hover {
      border-color: var(--gold);
      background: #fff;
      transform: translateY(-2px);
      box-shadow: 0 14px 28px rgba(40, 28, 18, 0.08), 0 4px 8px rgba(40, 28, 18, 0.04);
    }
    .hero-path__cta {
      display: inline-block;
      margin-top: 18px; padding-top: 14px;
      border-top: 1px dashed var(--line);
      font-family: var(--num-deco); font-weight: 400;
      font-size: 12px; letter-spacing: 0.10em;
      color: var(--gold);
      transition: letter-spacing 0.25s ease, color 0.25s ease;
    }
    a.hero-path:hover .hero-path__cta {
      color: var(--primary);
      letter-spacing: 0.14em;
    }
    .hero-path__tag {
      display: inline-block;
      font-family: var(--num-deco); font-weight: 400;
      font-size: 10px; letter-spacing: 0.20em;
      color: var(--gold);
      padding: 5px 14px;
      background: #fff;
      border: 1px solid var(--gold-soft);
      border-radius: 99px;
      margin-bottom: 14px;
      text-transform: uppercase;
    }
    .hero-path__title {
      font-family: var(--serif); font-weight: 500;
      font-size: clamp(16px, 2.0vw, 19px); letter-spacing: 0.10em;
      color: var(--primary);
      margin: 0 0 18px;
    }
    .hero-path__prices {
      display: flex; align-items: center; justify-content: center;
      gap: 10px; margin: 0 0 14px;
    }
    .hero-path__price {
      display: flex; flex-direction: column; align-items: center;
    }
    .hero-path__campaign,
    .price-campaign {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border: 1px solid rgba(177, 135, 55, 0.38);
      background: rgba(177, 135, 55, 0.08);
      color: var(--gold-dark);
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      line-height: 1.5;
    }
    .hero-path__campaign {
      margin: -4px 0 12px;
      padding: 4px 10px;
      border-radius: 999px;
    }
    .hero-path__plabel {
      font-size: 10.5px; color: var(--ink-sub);
      letter-spacing: 0.14em; margin-bottom: 6px;
    }
    .hero-path__pyen {
      font-family: var(--num-data); font-weight: 700;
      font-size: clamp(22px, 2.8vw, 30px); color: var(--primary);
      line-height: 1.0;
      font-variant-numeric: tabular-nums;
    }
    .hero-path__pyen small {
      font-family: var(--sans); font-weight: 500;
      font-size: 0.50em; margin-left: 3px;
      color: var(--primary);
    }
    .price-original,
    .hero-path__original {
      color: var(--ink-sub);
      text-decoration: line-through;
      text-decoration-thickness: 1px;
      text-decoration-color: rgba(122, 129, 143, 0.65);
      letter-spacing: 0.04em;
    }
    .hero-path__original {
      margin-top: 6px;
      font-size: 11px;
    }
    .hero-path__plus {
      font-family: var(--num-deco);
      font-size: 18px; color: var(--gold);
      align-self: center;
      margin-top: 16px;
    }
    .hero-path__note {
      font-size: 11.5px; color: var(--ink-sub);
      letter-spacing: 0.06em; line-height: 1.7;
      margin: 0;
    }
    .hero-path__note-line {
      display: block;
    }
    .hero-path__note strong { color: var(--primary); font-weight: 500; }
    .hero-features {
      display: flex; justify-content: center; flex-wrap: wrap;
      gap: 8px 18px; margin: 0 auto 28px;
      font-size: 11.5px; color: var(--ink-sub);
      letter-spacing: 0.08em;
    }
    .hero-features span::before {
      content: '✓ '; color: var(--gold);
      font-weight: 600; margin-right: 2px;
    }
    @media (max-width: 768px) {
      .hero { padding: 56px 0 40px; }
      .hero-cards { grid-template-columns: 1fr; gap: 10px; max-width: 320px; }
      .hero-card { padding: 18px 16px 16px; display: flex; align-items: center; justify-content: space-between; text-align: left; }
      .hero-card .label { margin-bottom: 0; font-size: 13px; }
      .hero-card .value { font-size: 22px; }
      .hero-card .sub { display: none; }
      .hero-paths { grid-template-columns: 1fr; gap: 12px; max-width: 360px; }
      .hero-path { padding: 22px 18px 20px; }
      .hero-path__prices { gap: 8px; }
      .hero-path__pyen { font-size: 24px; }
      .hero-path__note {
        max-width: 260px;
        margin-left: auto;
        margin-right: auto;
        font-size: 11px;
        line-height: 1.8;
        letter-spacing: 0.03em;
      }
      .hero-features { flex-direction: column; gap: 6px; align-items: center; }
    }

    /* CTA */
    .cta-btn {
      display: inline-block; padding: 20px 44px;
      background: var(--primary-deep); color: var(--paper);
      font-family: var(--sans); font-weight: 500; font-size: 15px;
      letter-spacing: 0.1em; border-radius: 2px;
      transition: background 0.3s ease, transform 0.3s ease;
    }
    .cta-btn:hover { background: var(--primary); color: var(--paper); transform: translateY(-2px); }
    .cta-btn .arrow { margin-left: 10px; opacity: 0.85; }
    .cta-btn--light {
      background: var(--paper); color: var(--primary-deep);
      border: 1px solid var(--primary-deep);
    }
    .cta-btn--light:hover { background: var(--primary-deep); color: var(--paper); }
    .contact-actions {
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 14px;
      flex-wrap: wrap;
      margin-top: 2px;
    }
    .line-contact-card {
      width: min(100%, 520px);
      margin: 30px auto 0;
      padding: 28px 24px;
      border: 1px solid var(--line);
      background: var(--paper);
      text-align: center;
    }
    .line-contact-card img {
      display: block;
      width: 132px;
      height: 132px;
      margin: 0 auto 16px;
    }
    .line-contact-card strong {
      display: block;
      font-family: var(--sans);
      color: var(--primary-deep);
      font-size: 16px;
      letter-spacing: 0.08em;
      margin-bottom: 8px;
    }
    .line-contact-card span {
      display: block;
      font-size: 13px;
      line-height: 1.85;
      color: var(--ink-sub);
    }
    .consult-flow {
      width: min(100%, 720px);
      margin: 34px auto 0;
      padding: 30px;
      border: 1px solid rgba(31,77,107,0.14);
      border-radius: 24px;
      background: rgba(255,255,255,0.86);
      box-shadow: 0 18px 50px rgba(31,77,107,0.08);
      text-align: left;
    }
    .consult-flow__head {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 22px;
    }
    .consult-flow__eyebrow {
      display: block;
      margin-bottom: 8px;
      font-family: var(--sans);
      font-size: 11px;
      letter-spacing: 0.18em;
      color: var(--gold);
      text-transform: uppercase;
    }
    .consult-flow__head strong {
      display: block;
      font-size: 22px;
      line-height: 1.5;
      font-weight: 500;
      color: var(--ink);
    }
    .consult-flow__badge {
      flex: 0 0 auto;
      padding: 8px 12px;
      border-radius: 999px;
      background: #eef5f7;
      color: var(--primary-deep);
      font-family: var(--sans);
      font-size: 12px;
      letter-spacing: 0.08em;
      white-space: nowrap;
    }
    .consult-step {
      padding: 22px 0;
      border-top: 1px solid rgba(31,77,107,0.12);
    }
    .consult-step__label {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 14px;
      font-family: var(--sans);
      font-size: 13px;
      letter-spacing: 0.08em;
      color: var(--ink-sub);
    }
    .consult-step__label span {
      color: var(--primary);
      font-weight: 600;
    }
    .consult-options {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }
    .consult-option {
      appearance: none;
      border: 1px solid rgba(31,77,107,0.16);
      border-radius: 16px;
      background: #fff;
      color: var(--ink);
      padding: 15px 16px;
      text-align: left;
      font-family: var(--serif);
      font-size: 15px;
      line-height: 1.5;
      cursor: pointer;
      transition: transform 0.25s ease, border-color 0.25s ease, background 0.25s ease, box-shadow 0.25s ease;
    }
    .consult-option:hover {
      transform: translateY(-2px);
      border-color: rgba(31,77,107,0.34);
      box-shadow: 0 12px 28px rgba(31,77,107,0.08);
    }
    .consult-option.is-selected {
      background: #f3f8fa;
      border-color: var(--primary);
      color: var(--primary-deep);
      box-shadow: inset 0 0 0 1px rgba(31,77,107,0.1);
    }
    .consult-flow__note {
      margin: 4px 0 20px;
      color: var(--ink-sub);
      font-size: 13px;
      line-height: 1.8;
      text-align: center;
    }
    .consult-flow__action {
      display: flex;
      justify-content: center;
      margin-top: 4px;
    }
    .consult-flow__action .cta-btn {
      border-radius: 999px;
      padding-inline: 34px;
    }
    .cta-sub { font-size: 12px; color: var(--ink-sub); margin-top: 14px; letter-spacing: 0.06em; }
    .cta-sub::before { content: "※ "; color: var(--gold); }
    .cta-block { text-align: center; margin: 36px 0 0; }
    .tool-actions {
      display: flex; justify-content: center; align-items: center;
      gap: 14px; flex-wrap: wrap; margin: 30px auto 0;
    }
    @media (max-width: 768px) {
      .cta-btn { padding: 17px 28px; font-size: 14px; width: 100%; max-width: 320px; }
      .contact-actions { flex-direction: column; gap: 10px; }
      .tool-actions { gap: 10px; margin-top: 24px; }
      .consult-flow { padding: 22px 16px; border-radius: 20px; }
      .consult-flow__head { display: block; text-align: center; }
      .consult-flow__head strong { font-size: 19px; }
      .consult-flow__badge { display: inline-block; margin-top: 14px; }
      .consult-options { display: flex; overflow-x: auto; gap: 10px; padding-bottom: 4px; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; }
      .consult-options::-webkit-scrollbar { display: none; }
      .consult-option { flex: 0 0 76%; scroll-snap-align: center; min-height: 86px; }
    }

    /* Pricing card */
    .price-card {
      max-width: 580px; margin: 0 auto;
      border: 1px solid var(--line); background: var(--paper);
      padding: 48px 40px;
    }
    .price-row { text-align: center; padding: 28px 0; }
    .price-row + .price-row { border-top: 1px solid var(--line); }
    .price-label {
      font-family: var(--sans); font-size: 13px; color: var(--ink-sub);
      letter-spacing: 0.2em; margin-bottom: 14px; font-weight: 500;
    }
    .price-yen {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: 56px; color: var(--primary);
      line-height: 1.0; letter-spacing: -0.01em;
    }
    .price-yen .yen-suffix { font-size: 22px; color: var(--primary); font-weight: 500; }
    .price-campaign {
      margin: 0 auto 16px;
      padding: 5px 12px;
      border-radius: 999px;
    }
    .price-original {
      margin: 0 0 10px;
      font-size: 14px;
    }
    .price-tax { font-size: 13px; color: var(--ink-sub); margin-top: 10px; letter-spacing: 0.05em; }
    .price-note { margin-top: 16px; font-size: 13px; color: var(--ink-sub); letter-spacing: 0.04em; line-height: 1.85; }
    @media (max-width: 768px) {
      .price-card { padding: 32px 20px; }
      .price-yen { font-size: 42px; }
      .price-yen .yen-suffix { font-size: 17px; }
    }
    .price-migration-note {
      max-width: 580px; margin: 20px auto 0;
      text-align: center;
      font-size: 12.5px; color: var(--ink-sub);
      letter-spacing: 0.04em; line-height: 1.85;
    }
    .price-migration-note__deal {
      display: block;
      margin-top: 4px;
    }
    .price-migration-note a {
      color: var(--primary); font-weight: 500;
      border-bottom: 1px solid var(--gold-soft);
      padding-bottom: 1px;
      transition: border-color 0.25s ease;
    }
    .price-migration-note a:hover {
      border-color: var(--gold);
    }
    .seo-option {
      max-width: 760px;
      margin: 34px auto 0;
      display: grid;
      grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr);
      gap: 22px;
      align-items: center;
      padding: 30px;
      border: 1px solid rgba(31, 77, 107, .12);
      border-radius: 24px;
      background: rgba(255,255,255,.74);
      box-shadow: 0 22px 60px rgba(20, 34, 49, .07);
    }
    .seo-option__label {
      display: block;
      margin: 0 0 12px;
      color: var(--primary);
      font-family: var(--num-data);
      font-size: 12px;
      letter-spacing: .24em;
      text-transform: uppercase;
    }
    .seo-option h3 {
      margin: 0 0 12px;
      font-family: var(--serif);
      font-size: 28px;
      font-weight: 500;
      line-height: 1.45;
    }
    .seo-option__price {
      margin: 0 0 14px;
      color: var(--primary);
      font-family: var(--num-data);
      font-size: 36px;
      font-weight: 700;
      line-height: 1.1;
      letter-spacing: 0;
    }
    .seo-option__price small {
      margin-left: 6px;
      color: var(--ink-sub);
      font-size: 13px;
      font-weight: 500;
      letter-spacing: .05em;
    }
    .seo-option p {
      margin: 0;
      color: var(--ink-sub);
      font-size: 14px;
      line-height: 1.9;
    }
    .seo-option__list {
      display: grid;
      gap: 10px;
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .seo-option__list li {
      position: relative;
      padding: 10px 0 10px 22px;
      border-bottom: 1px solid rgba(31,77,107,.10);
      color: #334155;
      font-size: 14px;
      line-height: 1.75;
    }
    .seo-option__list li::before {
      content: "─";
      position: absolute;
      left: 0;
      top: 10px;
      color: var(--primary);
    }
    @media (max-width: 768px) {
      .price-migration-note {
        max-width: 330px;
        padding: 0 10px;
        font-size: 12px;
        line-height: 1.9;
        letter-spacing: 0.01em;
      }
      .price-migration-note__deal {
        font-size: 11.5px;
      }
      .seo-option {
        grid-template-columns: 1fr;
        padding: 24px 18px;
        border-radius: 20px;
      }
      .seo-option h3 {
        font-size: 24px;
      }
      .seo-option__price {
        font-size: 31px;
      }
      .seo-option__list li {
        font-size: 13.5px;
      }
    }
    .payment-note {
      max-width: 780px;
      margin: 24px auto 0;
      padding: 18px;
      border: 1px solid rgba(31,77,107,0.13);
      background: rgba(255,255,255,0.72);
      box-shadow: 0 18px 42px rgba(31,77,107,0.06);
      text-align: left;
      display: grid;
      grid-template-columns: 180px minmax(0, 1fr);
      gap: 22px;
      align-items: center;
    }
    .payment-note__image {
      margin: 0;
      overflow: hidden;
      border-radius: 18px;
      aspect-ratio: 4 / 3;
      background: #eef3f6;
    }
    .payment-note__image img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .payment-note__label {
      display: block;
      margin-bottom: 8px;
      font-family: var(--num-deco);
      font-size: 12px;
      letter-spacing: 0.20em;
      color: var(--gold);
      text-transform: uppercase;
    }
    .payment-note strong {
      display: block;
      font-family: var(--serif);
      font-size: clamp(17px, 2.1vw, 22px);
      font-weight: 500;
      line-height: 1.72;
      letter-spacing: 0.04em;
      color: var(--primary-deep);
      text-wrap: balance;
    }
    .payment-note strong span {
      display: inline-block;
      white-space: nowrap;
    }
    .payment-note p {
      margin-top: 10px;
      font-size: 13px;
      line-height: 1.85;
      color: var(--ink-sub);
      letter-spacing: 0.04em;
    }
    @media (max-width: 768px) {
      .payment-note {
        grid-template-columns: 1fr;
        padding: 14px;
        margin-top: 20px;
        text-align: center;
      }
      .payment-note__image {
        max-height: 180px;
      }
      .payment-note strong {
        font-size: 17px;
        line-height: 1.65;
        letter-spacing: 0.02em;
      }
      .payment-note strong span {
        display: block;
        white-space: normal;
      }
      .payment-note p {
        font-size: 12.5px;
        text-align: left;
        line-height: 1.95;
      }
    }

    /* Two-plan layout */
    .plans {
      display: grid; grid-template-columns: 1fr 1fr; gap: 22px;
      max-width: 880px; margin: 0 auto;
    }
    .plan {
      background: var(--paper); border: 1px solid var(--line);
      padding: 40px 32px 36px; text-align: center;
      border-radius: 2px; position: relative;
      display: flex; flex-direction: column;
    }
    .plan--migration { background: var(--paper-warm); }
    .plan__tag {
      display: inline-block;
      font-family: var(--num-deco);
      font-size: 11px; letter-spacing: 0.22em;
      color: var(--gold);
      padding: 5px 14px;
      background: #fff;
      border: 1px solid var(--gold-soft);
      border-radius: 99px;
      margin: 0 auto 16px;
      text-transform: uppercase;
    }
    .plan__title {
      font-family: var(--serif); font-weight: 500;
      font-size: 22px; letter-spacing: 0.10em;
      color: var(--primary);
      margin: 0 0 8px;
    }
    .plan__desc {
      font-size: 12.5px; color: var(--ink-sub);
      letter-spacing: 0.06em; line-height: 1.85;
      margin: 0 0 26px;
    }
    .plan__row {
      padding: 22px 0;
      border-top: 1px solid var(--line);
    }
    .plan__row:last-of-type {
      border-bottom: 1px solid var(--line);
    }
    .plan__rlabel {
      font-family: var(--sans); font-size: 12px; color: var(--ink-sub);
      letter-spacing: 0.18em; margin-bottom: 10px; font-weight: 500;
    }
    .plan__yen {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: clamp(36px, 4.4vw, 48px);
      color: var(--primary); line-height: 1.0;
    }
    .plan__yen .yen-suffix {
      font-size: 0.45em; color: var(--primary); font-weight: 500;
      margin-left: 3px;
    }
    .plan__tax {
      font-size: 12px; color: var(--ink-sub);
      margin-top: 8px; letter-spacing: 0.05em;
    }
    .plan__plus {
      text-align: center; padding: 8px 0;
      font-family: var(--num-deco);
      font-size: 22px; color: var(--gold);
      line-height: 1;
    }
    .plan__note {
      margin: 20px 0 0;
      font-size: 12.5px; color: var(--ink-sub);
      letter-spacing: 0.04em; line-height: 1.85;
    }
    .plan__note strong { color: var(--primary); font-weight: 500; }
    .plan__highlight {
      margin-top: auto; padding-top: 20px;
      font-size: 12px; letter-spacing: 0.06em;
      color: var(--gold);
      border-top: 1px dashed var(--gold-soft);
      margin-top: 22px; padding-top: 14px;
    }
    @media (max-width: 768px) {
      .plans { grid-template-columns: 1fr; gap: 16px; max-width: 480px; }
      .plan { padding: 28px 22px 26px; }
      .plan__title { font-size: 18px; }
      .plan__yen { font-size: 36px; }
    }

    /* Atmosphere full-bleed image */
    .atmosphere {
      margin: 0; width: 100%; position: relative;
      background: var(--paper-warm); overflow: hidden;
    }
    .atmosphere--full img {
      display: block; width: 100%; height: auto;
      max-height: 60vh; object-fit: cover;
    }
    .atmosphere figcaption {
      position: absolute; left: 50%; bottom: 48px;
      transform: translateX(-50%);
      font-family: var(--serif); font-weight: 500;
      font-size: clamp(15px, 2.0vw, 22px);
      letter-spacing: 0.1em; color: #fff;
      text-align: center; max-width: calc(100% - 32px); white-space: nowrap;
      padding: 14px 28px;
      background: rgba(31, 77, 107, 0.78);
      -webkit-backdrop-filter: blur(8px);
      backdrop-filter: blur(8px);
      border-radius: 2px;
      text-shadow:
        0 0 8px rgba(0,0,0,0.5),
        0 2px 4px rgba(0,0,0,0.4);
      box-shadow: 0 6px 24px rgba(0,0,0,0.18);
      line-height: 1.7;
    }
    @media (max-width: 768px) {
      .atmosphere--full img { max-height: 50vh; }
      .atmosphere figcaption {
        bottom: 20px; font-size: 12.5px; letter-spacing: 0.04em;
        padding: 10px 16px; white-space: normal;
        line-height: 1.85;
        min-width: 70%; max-width: calc(100% - 24px);
      }
    }

    /* Pricing scarcity note */
    .pricing-note {
      max-width: 580px; margin: 32px auto 0;
      padding: 16px 20px; background: var(--gold-soft);
      text-align: center; font-size: 13px; line-height: 1.85;
      color: var(--ink-sub); letter-spacing: 0.04em;
    }
    .pricing-note strong { color: var(--primary); font-weight: 500; }
    @media (max-width: 768px) {
      .pricing-note { font-size: 12px; padding: 14px 16px; line-height: 1.85; }
    }

    /* Diff Block */
    .diff-block {
      max-width: 760px; margin: 0 auto; padding: 56px 32px;
      background: var(--paper); border: 1px solid var(--gold-soft); text-align: center;
    }
    .diff-block .preface { font-size: 14px; color: var(--ink-sub); margin-bottom: 32px; letter-spacing: 0.06em; }
    .diff-rows { display: grid; gap: 24px; max-width: 580px; margin: 0 auto 32px; }
    .diff-row {
      display: grid; grid-template-columns: 1fr; justify-items: center; gap: 10px;
      padding: 10px 0 4px;
    }
    .diff-row .pre, .diff-row .post { font-size: 14px; color: var(--ink-sub); letter-spacing: 0.05em; }
    .diff-row .pre, .diff-row .post { text-align: center; line-height: 1.6; }
    .diff-row .pre { font-weight: 500; }
    .diff-row .amount {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: clamp(34px, 5vw, 52px);
      color: var(--primary); line-height: 1.0; letter-spacing: -0.02em;
    }
    .diff-row .amount .yen-suffix { font-size: 0.45em; color: var(--primary); font-weight: 500; }
    .diff-block .footer-note { font-size: 13px; color: var(--ink-sub); margin-top: 16px; line-height: 1.8; }
    .diff-block .footer-note strong { color: var(--primary); font-weight: 500; }

    /* Investment Simulation Block */
    .invest-block {
      max-width: 760px; margin: 28px auto 0;
      padding: 40px 32px;
      background: linear-gradient(180deg, var(--paper-warm) 0%, #fff 100%);
      border: 1px solid var(--gold-soft); border-radius: 2px;
      text-align: center;
    }
    .invest-block__label {
      font-family: var(--num-deco); font-weight: 400;
      font-size: 12px; letter-spacing: 0.20em;
      color: var(--gold); text-transform: uppercase;
      margin: 0 0 8px;
    }
    .invest-block__heading {
      font-family: var(--serif); font-weight: 500;
      font-size: clamp(16px, 2.0vw, 19px); letter-spacing: 0.08em;
      color: var(--primary);
      margin: 0 0 8px;
    }
    .invest-block__desc {
      font-size: 12.5px; color: var(--ink-sub);
      letter-spacing: 0.04em; line-height: 1.85;
      margin: 0 0 28px;
    }
    .invest-rows {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
      max-width: 640px; margin: 0 auto 24px;
    }
    .invest-row {
      padding: 22px 14px;
      background: #fff; border: 1px solid var(--line);
      border-radius: 2px;
      display: flex; flex-direction: column; align-items: center; gap: 8px;
    }
    .invest-row--final { background: var(--gold-soft); border-color: var(--gold); }
    .invest-row__period {
      font-family: var(--sans); font-weight: 500;
      font-size: 12px; letter-spacing: 0.10em;
      color: var(--ink-sub);
    }
    .invest-row--final .invest-row__period { color: var(--primary); font-weight: 600; }
    .invest-row__amount {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: clamp(28px, 3.4vw, 36px);
      color: var(--primary); line-height: 1.0; letter-spacing: -0.01em;
    }
    .invest-row__amount .yen-suffix {
      font-size: 0.45em; color: var(--primary);
      font-weight: 500; margin-left: 3px;
    }
    .invest-row__detail {
      font-size: 10.5px; color: var(--ink-sub);
      letter-spacing: 0.04em; line-height: 1.6;
    }
    .invest-disclaimer {
      max-width: 580px; margin: 0 auto;
      font-size: 11px; color: var(--ink-sub);
      letter-spacing: 0.04em; line-height: 1.85;
      text-align: left;
    }
    @media (max-width: 768px) {
      .invest-block { padding: 32px 18px; }
      .invest-rows { grid-template-columns: 1fr; gap: 12px; max-width: 360px; }
      .invest-row { padding: 18px 14px; }
      .invest-row__amount { font-size: 24px; }
    }
    @media (max-width: 768px) {
      .diff-block { padding: 40px 16px; }
      .diff-rows { gap: 28px; }
      .diff-row { gap: 6px; }
      .diff-row .pre,
      .diff-row .post {
        font-size: 12.5px;
        text-align: center;
        line-height: 1.6;
      }
      .diff-row .pre br { display: none; }
      .diff-row .amount {
        font-size: clamp(34px, 9vw, 44px);
        white-space: nowrap;
      }
    }

    /* Included list */
    .included { max-width: 720px; margin: 40px auto 0; }
    .included h4 {
      text-align: center; font-family: var(--num-deco); font-weight: 400;
      font-size: 12px; color: var(--gold); letter-spacing: 0.3em;
      text-transform: uppercase; margin-bottom: 24px;
    }
    .included ul {
      list-style: none; padding: 0; margin: 0;
      display: grid; grid-template-columns: 1fr 1fr; gap: 0;
    }
    .included li {
      padding: 16px 4px 16px 24px; border-bottom: 1px solid var(--line);
      font-size: 14px; color: var(--ink); position: relative;
    }
    .included li::before {
      content: ""; position: absolute; left: 0; top: 24px;
      width: 12px; height: 1px; background: var(--gold);
    }
    @media (max-width: 768px) { .included ul { grid-template-columns: 1fr; } }

    /* Start guide */
    .start-guide {
      background: var(--paper);
      border-top: 1px solid var(--line);
      border-bottom: 1px solid var(--line);
    }
    .start-guide__grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(300px, 1fr));
      gap: 18px;
      margin-top: 36px;
    }
    .start-guide__card {
      background: rgba(255,255,255,.82);
      border: 1px solid var(--line);
      border-radius: 24px;
      padding: 28px;
      box-shadow: 0 18px 46px rgba(15, 23, 42, 0.04);
    }
    .start-guide__label {
      display: block;
      margin-bottom: 18px;
      font-family: var(--num-deco);
      font-size: 11px;
      letter-spacing: .24em;
      text-transform: uppercase;
      color: var(--gold);
    }
    .start-guide__card h3 {
      margin: 0 0 14px;
      font-size: 22px;
      line-height: 1.55;
    }
    .start-guide__card p {
      margin: 0 0 18px;
      color: var(--ink-sub);
      font-size: 14px;
      line-height: 1.9;
    }
    .start-guide__list {
      list-style: none;
      margin: 0;
      padding: 0;
      display: grid;
      gap: 10px;
    }
    .start-guide__list li {
      position: relative;
      padding-left: 18px;
      color: var(--ink);
      font-size: 13.5px;
      line-height: 1.75;
    }
    .start-guide__list li::before {
      content: "";
      position: absolute;
      left: 0;
      top: .86em;
      width: 8px;
      height: 1px;
      background: var(--primary);
    }
    .start-guide__note {
      max-width: 760px;
      margin: 26px auto 0;
      padding: 18px 22px;
      border: 1px solid rgba(37, 99, 235, .16);
      background: rgba(255,255,255,.68);
      color: var(--ink-sub);
      font-size: 13px;
      line-height: 1.9;
      text-align: center;
    }
    .start-guide__note strong {
      color: var(--primary);
      font-weight: 600;
    }
    @media (max-width: 980px) {
      .start-guide__grid {
        grid-template-columns: 1fr;
        max-width: 560px;
        margin-left: auto;
        margin-right: auto;
      }
    }
    @media (max-width: 640px) {
      .start-guide__grid { gap: 12px; margin-top: 28px; }
      .start-guide__card { padding: 22px 18px; border-radius: 20px; }
      .start-guide__card h3 { font-size: 19px; }
      .start-guide__card p,
      .start-guide__list li { font-size: 13px; }
      .start-guide__note { text-align: left; padding: 16px; }
    }

    /* Comparison */
    .compare-wrap { max-width: 920px; margin: 0 auto; overflow-x: auto; -webkit-overflow-scrolling: touch; }
    .compare { width: 100%; border-collapse: collapse; font-size: 14px; }
    .compare thead th {
      font-family: var(--serif); font-weight: 500; font-size: 15px;
      padding: 22px 18px; text-align: left;
      border-bottom: 2px solid var(--line); letter-spacing: 0.04em;
    }
    .compare thead th.col-bad { color: var(--warn); background: var(--warn-soft); }
    .compare thead th.col-good { color: var(--primary); background: var(--gold-soft); }
    .compare tbody td { padding: 20px 18px; border-bottom: 1px solid var(--line); vertical-align: top; line-height: 1.65; }
    .compare tbody td:first-child {
      font-weight: 500; color: var(--ink); font-size: 13px; letter-spacing: 0.05em;
    }
    .compare tbody td.col-bad { background: rgba(168, 93, 93, 0.04); color: var(--ink-sub); }
    .compare tbody td.col-good { background: rgba(201, 169, 110, 0.06); color: var(--ink); font-weight: 500; }
    .compare .num {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: 16px; letter-spacing: -0.01em;
    }
    .compare tbody td.col-bad .num { color: var(--warn); }
    .compare tbody td.col-good .num { color: var(--primary); }
    @media (max-width: 768px) {
      .compare { min-width: 540px; }
      .compare-wrap { margin: 0 -4%; padding: 0 4%; }
    }

    /* Reasons */
    .reasons { max-width: 800px; margin: 0 auto; counter-reset: reason; }
    .reason {
      padding: 36px 0; border-bottom: 1px solid var(--line);
      counter-increment: reason; display: grid;
      grid-template-columns: 80px 1fr; gap: 24px; align-items: start;
    }
    .reason:last-child { border-bottom: none; }
    .reason::before {
      content: "Reason " counter(reason);
      font-family: var(--num-deco); font-size: 13px; color: var(--gold);
      letter-spacing: 0.2em; text-transform: uppercase; margin-top: 6px;
    }
    .reason h3 { font-family: var(--serif); font-weight: 500; font-size: 18px; margin-bottom: 10px; }
    .reason p { font-size: 14px; color: var(--ink-sub); line-height: 1.95; margin: 0; }
    @media (max-width: 768px) { .reason { grid-template-columns: 1fr; gap: 6px; padding: 28px 0; } }

    /* Split */
    .split-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; max-width: 920px; margin: 0 auto; }
    @media (max-width: 768px) { .split-2 { grid-template-columns: 1fr; gap: 20px; } }
    .panel { padding: 36px 32px; border: 1px solid var(--line); background: var(--paper); }
    .panel.gold-tint { background: rgba(201, 169, 110, 0.06); border-color: var(--gold-soft); }
    .panel.warn-tint { background: rgba(168, 93, 93, 0.04); border-color: var(--warn-soft); }
    .panel h3 { margin-bottom: 16px; color: var(--primary); }
    .panel.warn-tint h3 { color: var(--warn); }
    .panel ul { list-style: none; padding: 0; margin: 14px 0 0; }
    .panel li {
      padding: 11px 0 11px 22px; border-bottom: 1px solid var(--line-soft);
      font-size: 14px; line-height: 1.75; position: relative;
    }
    .panel li:last-child { border-bottom: none; }
    .panel li::before { content: ""; position: absolute; left: 0; top: 22px; width: 10px; height: 1px; background: var(--gold); }
    .panel.warn-tint li::before { background: var(--warn); }

    /* Lost cost block (story) */
    .lost-block {
      max-width: 480px; margin: 48px auto;
      padding: 36px 24px; text-align: center;
      border: 1px solid var(--warn-soft);
      background: rgba(168, 93, 93, 0.03);
    }
    .lost-row { display: flex; align-items: baseline; justify-content: center; gap: 16px; margin: 8px 0; }
    .lost-label { font-size: 13px; color: var(--ink-sub); letter-spacing: 0.15em; min-width: 60px; text-align: right; }
    .lost-amount {
      font-family: var(--num-data); font-variant-numeric: tabular-nums; font-weight: 700;
      font-size: 28px; color: var(--warn); letter-spacing: -0.01em; line-height: 1.1;
      min-width: 200px; text-align: left;
    }
    .lost-amount.big { font-size: 36px; }
    .lost-amount .yen-suffix { font-size: 0.55em; color: var(--warn); font-weight: 500; }
    .lost-arrow { color: var(--warn); opacity: 0.5; font-size: 14px; margin: 4px 0; }
    .lost-caption {
      margin-top: 24px; font-size: 13px; color: var(--ink-sub);
      line-height: 1.85; letter-spacing: 0.04em;
    }
    @media (max-width: 768px) {
      .lost-block { padding: 28px 16px; }
      .lost-row { flex-wrap: wrap; gap: 8px; }
      .lost-amount { font-size: 22px; min-width: auto; }
      .lost-amount.big { font-size: 28px; }
    }

    /* Responsive line-break helpers */
    .sp-only { display: none; }
    @media (max-width: 768px) {
      .sp-only { display: inline; }
      .pc-only { display: none; }
    }

    /* Doctor portrait (story section) */
    .doctor-portrait {
      max-width: 320px; margin: 8px auto 48px; text-align: center;
    }
    .doctor-portrait img {
      display: block; width: 100%; height: auto;
      max-width: 280px; margin: 0 auto 18px;
    }
    .doctor-portrait figcaption {
      display: flex; flex-direction: column; gap: 4px;
      padding-top: 16px; border-top: 1px solid var(--gold-soft);
    }
    .doctor-portrait__name {
      font-family: var(--serif); font-weight: 500; font-size: 18px;
      letter-spacing: 0.15em; color: var(--ink);
    }
    .doctor-portrait__role {
      font-family: var(--sans); font-size: 12px; color: var(--ink-sub);
      letter-spacing: 0.1em;
    }
    .doctor-portrait__cert {
      font-family: var(--num-deco); font-size: 11px; color: var(--gold);
      letter-spacing: 0.2em; text-transform: uppercase;
    }
    @media (max-width: 768px) {
      .doctor-portrait { max-width: 240px; margin: 4px auto 32px; }
      .doctor-portrait img { max-width: 220px; }
    }

    /* Story */
    .body-text { font-size: 16px; line-height: 1.95; }
    .body-text p { margin-bottom: 1.5em; }
    .highlight { background: linear-gradient(transparent 65%, var(--gold-soft) 65%); padding: 0 2px; font-weight: 500; }
    .body-text strong { color: var(--primary); font-weight: 500; }
    .pullquote {
      font-family: var(--serif); font-size: clamp(20px, 2.4vw, 24px);
      line-height: 1.85; color: var(--primary); text-align: center;
      max-width: 720px; margin: 56px auto; padding: 0 32px; letter-spacing: 0.04em;
    }
    @media (max-width: 768px) { .pullquote { font-size: 18px; padding: 0 12px; margin: 36px auto; } }

    /* Metaphor */
    .metaphor {
      max-width: 880px; margin: 48px auto 0;
      display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: stretch;
    }
    .metaphor-card { padding: 36px 24px; border: 1px solid var(--line); text-align: center; background: var(--paper); }
    .metaphor-card.bad { background: rgba(168, 93, 93, 0.03); border-color: var(--warn-soft); }
    .metaphor-card.good { background: rgba(201, 169, 110, 0.05); border-color: var(--gold-soft); }
    .metaphor-card svg { display: block; margin: 0 auto 20px; }
    .metaphor-card h4 { font-family: var(--serif); font-weight: 500; font-size: 16px; letter-spacing: 0.05em; margin-bottom: 12px; }
    .metaphor-card.bad h4 { color: var(--warn); }
    .metaphor-card.good h4 { color: var(--primary); }
    .metaphor-card p { font-size: 13px; color: var(--ink-sub); line-height: 1.85; margin: 0; }
    @media (max-width: 768px) { .metaphor { grid-template-columns: 1fr; gap: 16px; } }

    /* Timing */
    .timing-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px;
      max-width: 880px; margin: 32px auto 0;
    }
    .timing-card { padding: 32px 24px; border: 1px solid var(--line); background: var(--paper); text-align: center; }
    .timing-card .label { font-family: var(--sans); font-size: 12px; color: var(--ink-sub); letter-spacing: 0.12em; margin-bottom: 14px; font-weight: 500; }
    .timing-card .value {
      font-family: var(--num-data); font-variant-numeric: tabular-nums; font-weight: 700;
      font-size: clamp(22px, 2.6vw, 26px); color: var(--primary); line-height: 1.2;
      letter-spacing: -0.01em; margin-bottom: 10px;
    }
    .timing-card .desc { font-size: 13px; color: var(--ink-sub); line-height: 1.75; }
    @media (max-width: 768px) { .timing-grid { grid-template-columns: 1fr; gap: 12px; } }

    /* Steps */
    .steps { max-width: 760px; margin: 0 auto; }
    .step {
      display: grid; grid-template-columns: 100px 1fr; gap: 28px;
      padding: 32px 0; border-bottom: 1px solid var(--line); align-items: start;
    }
    .step:last-child { border-bottom: none; }
    .step-num {
      font-family: var(--num-data); font-variant-numeric: tabular-nums; font-weight: 700;
      font-size: 36px; color: var(--gold); line-height: 1.0; letter-spacing: -0.01em;
    }
    .step-num small {
      display: block; font-family: var(--num-deco); font-weight: 400;
      font-size: 11px; letter-spacing: 0.3em; text-transform: uppercase;
      margin-top: 6px; color: var(--gold);
    }
    .step h3 { font-family: var(--serif); font-weight: 500; font-size: 18px; margin-bottom: 8px; color: var(--ink); }
    .step p { font-size: 14px; color: var(--ink-sub); line-height: 1.85; margin: 0; }
    @media (max-width: 768px) {
      .step { grid-template-columns: 1fr; gap: 6px; padding: 24px 0; }
      .step-num { font-size: 26px; }
    }

    /* Vision Interview tool */
    #vision-tool { padding: 96px 0; background: var(--paper); }
    .vision-categories {
      list-style: none; padding: 0; margin: 8px auto 32px;
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
      max-width: 720px;
    }
    .vision-categories li {
      background: var(--paper); border: 1px solid var(--line);
      padding: 32px 16px 28px; text-align: center;
      display: flex; flex-direction: column; align-items: center; gap: 14px;
    }
    .vision-cat__icon {
      width: 56px; height: 56px;
      border-radius: 50%;
      background: var(--gold-soft);
      display: flex; align-items: center; justify-content: center;
    }
    .vision-cat__icon svg { width: 28px; height: 28px; }
    .vision-cat__label {
      font-family: var(--serif); font-weight: 500;
      font-size: 16px; letter-spacing: 0.08em;
      color: var(--ink);
    }
    .vision-meta {
      text-align: center; font-size: 13px; color: var(--ink-sub);
      letter-spacing: 0.06em; margin: 0 0 32px !important;
    }
    .vision-tool__note {
      max-width: 720px; margin: 0 auto !important;
      padding: 20px 24px; background: var(--gold-soft);
      text-align: center; font-size: 13px !important;
      line-height: 1.95 !important; color: var(--ink-sub) !important;
      letter-spacing: 0.04em;
    }
    .vision-tool__note strong { color: var(--primary); font-weight: 500; }
    @media (max-width: 768px) {
      #vision-tool { padding: 56px 0; }
      .vision-categories { grid-template-columns: 1fr; gap: 12px; max-width: 320px; }
      .vision-categories li {
        flex-direction: row; padding: 18px 20px; gap: 16px; text-align: left;
      }
      .vision-cat__icon { width: 44px; height: 44px; flex-shrink: 0; }
      .vision-cat__icon svg { width: 22px; height: 22px; }
      .vision-tool__note { padding: 16px 18px; text-align: left; }
    }

    /* Design Preference Diagnostic */
    #design-tool { padding: 96px 0; }
    .design-categories {
      list-style: none; padding: 0; margin: 8px auto 32px;
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;
      max-width: 760px;
    }
    .design-categories li {
      background: var(--paper); border: 1px solid var(--line);
      padding: 22px 16px 18px; text-align: center; border-radius: 2px;
      transition: border-color 0.3s ease, transform 0.3s ease;
    }
    .design-categories li:hover {
      border-color: var(--gold); transform: translateY(-2px);
    }
    .design-cat__label {
      display: block;
      font-family: var(--serif); font-weight: 500;
      font-size: 15px; letter-spacing: 0.08em; color: var(--ink);
      margin-bottom: 8px;
    }
    .design-cat__example {
      display: block;
      font-family: var(--num-deco); font-weight: 400;
      font-size: 11px; color: var(--gold);
      letter-spacing: 0.1em;
    }
    @media (max-width: 768px) {
      #design-tool { padding: 56px 0; }
      .design-categories { grid-template-columns: 1fr 1fr; gap: 10px; max-width: 380px; }
      .design-categories li { padding: 16px 10px 14px; }
      .design-cat__label { font-size: 14px; }
      .design-cat__example { font-size: 10px; }
    }

    /* ===== Phone-on-Cafe Photo ===== */
    .phone-cafe {
      max-width: 460px; margin: 8px auto 36px;
      padding: 0;
    }
    .phone-cafe picture { display: block; }
    .phone-cafe img {
      display: block; width: 100%; height: auto;
      border-radius: 4px;
      box-shadow:
        0 22px 44px rgba(40, 28, 18, 0.18),
        0 6px 14px rgba(40, 28, 18, 0.12);
    }
    .phone-cafe figcaption {
      margin-top: 14px; text-align: center;
      font-family: var(--serif); font-weight: 400;
      font-size: 13px; letter-spacing: 0.10em;
      color: var(--ink-sub);
    }
    @media (max-width: 768px) {
      .phone-cafe { max-width: 320px; margin-bottom: 28px; }
      .phone-cafe figcaption { font-size: 12px; }
    }

    /* Migration Concierge */
    #migration { padding: 96px 0; background: var(--paper); }
    .migration-concept {
      max-width: 720px; margin: 8px auto 56px;
      text-align: center; padding: 28px 24px;
      background: var(--gold-soft); border-radius: 2px;
    }
    .migration-concept__title {
      font-family: var(--serif); font-weight: 500;
      font-size: clamp(18px, 2.4vw, 22px); color: var(--primary);
      margin-bottom: 14px; letter-spacing: 0.06em;
    }
    .migration-concept__title strong {
      color: var(--primary); font-weight: 700;
      background: linear-gradient(transparent 60%, #fff 60%); padding: 0 4px;
    }
    .migration-concept__desc {
      font-size: 14px; line-height: 2.0; color: var(--ink); margin: 0;
      letter-spacing: 0.04em;
    }
    .migration-proof {
      max-width: 720px;
      margin: -34px auto 56px;
      padding: 24px 26px;
      border: 1px solid rgba(44, 95, 127, 0.18);
      border-radius: 24px;
      background: #fff;
      box-shadow: 0 14px 36px rgba(15, 23, 42, 0.06);
    }
    .migration-proof__label {
      display: block;
      margin-bottom: 8px;
      font-family: var(--num-deco);
      font-size: 11px;
      color: var(--gold);
      letter-spacing: 0.22em;
      text-transform: uppercase;
    }
    .migration-proof p {
      margin: 0;
      font-size: 14px;
      line-height: 1.95;
      color: var(--ink-sub);
      letter-spacing: 0.04em;
    }
    .migration-proof strong {
      color: var(--primary);
      font-weight: 600;
    }
    .migration-steps {
      list-style: none; padding: 0; margin: 0 auto 64px;
      max-width: 720px;
    }
    .migration-steps > li {
      display: grid; grid-template-columns: 56px 1fr; gap: 24px;
      padding: 28px 0; border-bottom: 1px solid var(--line);
      align-items: start;
    }
    .migration-steps > li:last-child { border-bottom: none; }
    .migration-step__num {
      width: 44px; height: 44px; border-radius: 50%;
      background: var(--primary); color: var(--paper);
      display: flex; align-items: center; justify-content: center;
      font-family: var(--num-data); font-weight: 700; font-size: 18px;
      letter-spacing: -0.02em;
    }
    .migration-step__body h3 {
      font-family: var(--serif); font-weight: 500;
      font-size: 18px; line-height: 1.6; margin: 6px 0 10px;
      color: var(--ink); letter-spacing: 0.04em;
    }
    .migration-step__body p {
      font-size: 14px; line-height: 1.95; color: var(--ink-sub);
      margin: 0 0 14px; letter-spacing: 0.04em;
    }
    .migration-step__bubble {
      padding: 14px 18px; border-radius: 12px; margin: 0;
      font-size: 13px; line-height: 1.85; max-width: 90%;
    }
    .migration-step__bubble p { margin: 0; color: var(--ink); }
    .migration-step__bubble-label {
      display: block; font-family: var(--num-deco);
      font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase;
      color: var(--ink-sub); margin-bottom: 6px;
    }
    .migration-step__bubble--ours {
      background: rgba(44, 95, 127, 0.08); border-left: 3px solid var(--primary);
    }
    .migration-step__bubble--doctor {
      background: rgba(201, 169, 110, 0.12); border-left: 3px solid var(--gold);
      margin-left: auto;
    }
    .migration-step__bubble--vendor {
      background: var(--paper-warm); border-left: 3px solid var(--ink-sub);
    }
    .migration-pricing {
      max-width: 880px; margin: 0 auto 48px;
      padding: 40px 32px; background: var(--paper-warm); border-radius: 2px;
    }
    .migration-pricing__heading {
      text-align: center; font-family: var(--serif); font-weight: 500;
      font-size: 18px; color: var(--ink); margin: 0 0 32px;
      letter-spacing: 0.1em;
    }
    .migration-pricing__cards {
      display: grid; grid-template-columns: 1fr 1fr; gap: 24px;
    }
    .migration-pricing__card {
      background: var(--paper); padding: 32px 24px; border-radius: 2px;
      border: 1px solid var(--line); text-align: center;
    }
    .migration-pricing__label {
      font-family: var(--sans); font-size: 12px; font-weight: 500;
      color: var(--ink-sub); letter-spacing: 0.2em; margin-bottom: 14px;
    }
    .migration-pricing__yen {
      font-family: var(--num-data); font-variant-numeric: tabular-nums;
      font-weight: 700; font-size: 38px; color: var(--primary);
      line-height: 1.0; letter-spacing: -0.01em; margin-bottom: 6px;
    }
    .migration-pricing__yen .yen-suffix { font-size: 18px; color: var(--primary); font-weight: 500; }
    .migration-pricing__tax {
      font-size: 12px; color: var(--ink-sub); margin-bottom: 16px;
      letter-spacing: 0.04em;
    }
    .migration-pricing__note {
      font-size: 13px; line-height: 1.85; color: var(--ink); margin: 0;
      letter-spacing: 0.03em;
    }
    .migration-pricing__note strong { color: var(--primary); font-weight: 500; }
    .migration-pricing__note small {
      display: block; margin-top: 8px;
      font-size: 11px; color: var(--ink-sub); line-height: 1.7;
    }
    /* Migration Total — 合計サマリー */
    .migration-total {
      max-width: 820px; margin: 0 auto 32px;
      padding: 36px 32px;
      background: linear-gradient(135deg, #fdf9ee 0%, #faf3df 100%);
      border: 1px solid rgba(166, 142, 91, 0.28);
      border-radius: 4px;
      text-align: center;
    }
    .migration-total__heading {
      margin: 0 0 22px;
      font-family: var(--font-jp-serif);
      font-size: 16px; letter-spacing: 0.10em;
      color: var(--primary); font-weight: 500;
    }
    .migration-total__formula {
      display: flex; flex-wrap: wrap;
      justify-content: center; align-items: stretch;
      gap: 14px;
      margin: 0 0 26px;
    }
    .migration-total__item {
      display: inline-flex; flex-direction: column;
      justify-content: center; align-items: center;
      min-width: 150px; padding: 14px 18px;
      background: #fff;
      border: 1px solid rgba(166, 142, 91, 0.22);
      border-radius: 3px;
    }
    .migration-total__item--final {
      background: var(--primary); border-color: var(--primary);
    }
    .migration-total__label {
      display: block;
      font-size: 11px; letter-spacing: 0.18em;
      color: var(--ink-sub); margin-bottom: 6px;
    }
    .migration-total__item--final .migration-total__label {
      color: rgba(255, 255, 255, 0.78);
    }
    .migration-total__amount {
      font-family: var(--font-en-serif);
      font-size: 28px; font-weight: 400;
      color: var(--ink);
      letter-spacing: 0.02em;
      font-variant-numeric: tabular-nums;
    }
    .migration-total__amount small {
      font-size: 13px; margin-left: 3px;
      font-family: var(--font-jp-serif);
      color: var(--ink-sub);
    }
    .migration-total__amount--final {
      font-family: var(--font-jp-serif);
      font-size: 18px; color: #fff;
      letter-spacing: 0.10em;
    }
    .migration-total__plus {
      display: inline-flex; align-items: center;
      font-family: var(--font-en-serif);
      font-size: 22px; color: var(--primary);
      font-weight: 300;
    }
    .migration-total__notes {
      max-width: 600px; margin: 0 auto;
      padding-top: 20px;
      border-top: 1px dashed rgba(166, 142, 91, 0.30);
      text-align: left;
    }
    .migration-total__notes p {
      margin: 0 0 8px;
      font-size: 13px; line-height: 1.85;
      color: var(--ink); letter-spacing: 0.03em;
    }
    .migration-total__notes p:last-child { margin-bottom: 0; }
    .migration-total__notes strong {
      color: var(--primary); font-weight: 600;
    }
    .migration-warning {
      max-width: 720px; margin: 0 auto;
      padding: 20px 24px; background: var(--warn-soft);
      border-left: 4px solid var(--warn); border-radius: 2px;
      font-size: 13px; line-height: 1.95; color: var(--ink);
      letter-spacing: 0.03em;
    }
    .migration-warning p { margin: 0; }
    .migration-warning strong { color: var(--warn); font-weight: 600; }
    .migration-warning small {
      display: block; margin-top: 6px;
      font-size: 11px; color: var(--ink-sub);
    }
    @media (max-width: 768px) {
      #migration { padding: 56px 0; }
      .migration-concept { padding: 22px 18px; margin-bottom: 40px; }
      .migration-steps > li { grid-template-columns: 40px 1fr; gap: 16px; padding: 22px 0; }
      .migration-step__num { width: 36px; height: 36px; font-size: 15px; }
      .migration-step__body h3 { font-size: 16px; }
      .migration-step__body p { font-size: 13px; }
      .migration-step__bubble { font-size: 12px; padding: 12px 14px; max-width: 100%; }
      .migration-pricing { padding: 28px 18px; }
      .migration-pricing__cards { grid-template-columns: 1fr; gap: 16px; }
      .migration-pricing__card { padding: 24px 18px; }
      .migration-pricing__yen { font-size: 32px; }
      .migration-total { padding: 26px 18px; margin-bottom: 28px; }
      .migration-total__heading { font-size: 14px; margin-bottom: 18px; }
      .migration-total__formula { gap: 10px; margin-bottom: 22px; flex-direction: column; }
      .migration-total__item { width: 100%; min-width: 0; padding: 12px 14px; }
      .migration-total__amount { font-size: 24px; }
      .migration-total__amount--final { font-size: 16px; }
      .migration-total__plus { font-size: 18px; }
      .migration-total__notes p { font-size: 12.5px; }
      .migration-warning { padding: 16px 18px; font-size: 12.5px; }
    }

    /* Client Works */
    #client-works {
      padding: 104px 0;
      background:
        radial-gradient(circle at 18% 0%, rgba(180, 147, 92, 0.10), transparent 34%),
        linear-gradient(180deg, #fff 0%, #f6f8fb 100%);
      border-top: 1px solid var(--line);
      border-bottom: 1px solid var(--line);
    }
    .client-works__head {
      max-width: 760px;
      margin: 0 auto 42px;
      text-align: center;
    }
    .client-works__lead {
      margin: 18px auto 0;
      color: var(--ink-sub);
      font-size: 15px;
      line-height: 2;
      letter-spacing: 0.05em;
    }
    .client-works__grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 24px;
      align-items: stretch;
    }
    .client-work-card {
      display: flex;
      flex-direction: column;
      min-width: 0;
      overflow: hidden;
      border: 1px solid rgba(119, 137, 154, 0.20);
      border-radius: 28px;
      background: rgba(255, 255, 255, 0.92);
      box-shadow: 0 24px 60px rgba(31, 41, 51, 0.08);
    }
    .client-work-card__media {
      position: relative;
      overflow: hidden;
      aspect-ratio: 16 / 10;
      background: #eef3f6;
    }
    .client-work-card__media img {
      width: 100%;
      height: 100%;
      display: block;
      object-fit: cover;
      object-position: top center;
      transform: scale(1.01);
    }
    .client-work-card__body {
      display: flex;
      flex-direction: column;
      gap: 14px;
      flex: 1;
      padding: 26px 26px 28px;
    }
    .client-work-card__type {
      color: var(--gold);
      font-family: var(--num-deco);
      font-size: 11px;
      letter-spacing: 0.22em;
      text-transform: uppercase;
    }
    .client-work-card__name {
      margin: 0;
      color: var(--ink);
      font-family: var(--font-jp-serif);
      font-size: clamp(22px, 2.2vw, 30px);
      font-weight: 500;
      line-height: 1.45;
      letter-spacing: 0.04em;
    }
    .client-work-card__text {
      margin: 0;
      color: var(--ink-sub);
      font-size: 14px;
      line-height: 1.9;
      letter-spacing: 0.04em;
    }
    .client-work-card__link {
      margin-top: auto;
      color: var(--primary);
      font-family: var(--sans);
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-decoration: none;
    }
    .client-work-card__link:hover {
      color: var(--primary-deep);
    }
    .client-works__note {
      margin: 30px auto 0;
      max-width: 820px;
      padding: 18px 24px;
      border: 1px solid rgba(119, 137, 154, 0.18);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.72);
      color: var(--ink-sub);
      font-size: 13px;
      line-height: 1.85;
      letter-spacing: 0.04em;
      text-align: center;
    }
    @media (max-width: 1120px) {
      .client-works__grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 24px;
      }
    }
    @media (max-width: 860px) {
      #client-works { padding: 68px 0; }
      .client-works__head { margin-bottom: 28px; text-align: left; }
      .client-works__lead { font-size: 13.5px; line-height: 1.9; }
      .client-works__grid { grid-template-columns: 1fr; gap: 18px; }
      .client-work-card { border-radius: 24px; }
      .client-work-card__media { aspect-ratio: 16 / 11; }
      .client-work-card__body { padding: 22px 20px 24px; }
      .client-work-card__name {
        font-size: 23px;
        line-height: 1.5;
      }
      .client-work-card__text {
        font-size: 13px;
        line-height: 1.85;
      }
      .client-works__note {
        margin-top: 22px;
        padding: 15px 16px;
        text-align: left;
      }
    }

    /* Intro Video */
    #intro-video { padding: 96px 0; }
    .intro-video {
      display: grid; grid-template-columns: minmax(260px, 340px) 1fr; gap: 64px;
      max-width: 920px; margin: 0 auto;
      align-items: center;
    }
    .intro-video__frame {
      position: relative;
      width: 100%; aspect-ratio: 9 / 16;
      border-radius: 16px; overflow: hidden;
      background: var(--ink);
      box-shadow:
        0 22px 50px rgba(40, 28, 18, 0.18),
        0 8px 16px rgba(40, 28, 18, 0.12);
    }
    .intro-video__player {
      width: 100%; height: 100%;
      display: block; object-fit: cover;
    }
    .intro-video__text {
      padding: 8px 0;
    }
    .intro-video__overline {
      font-family: var(--num-deco); font-weight: 400;
      font-size: 11px; letter-spacing: 0.22em;
      color: var(--gold); text-transform: uppercase;
      margin: 0 0 24px;
    }
    .intro-video__points {
      list-style: none; padding: 0; margin: 0 0 22px;
      display: flex; flex-direction: column; gap: 18px;
    }
    .intro-video__points li {
      display: grid; grid-template-columns: 36px 1fr; gap: 16px;
      align-items: start;
      padding-bottom: 18px;
      border-bottom: 1px solid var(--line-soft);
    }
    .intro-video__points li:last-child { border-bottom: none; padding-bottom: 0; }
    .intro-video__no {
      font-family: var(--num-deco); font-weight: 400;
      font-size: 18px; color: var(--gold);
      letter-spacing: 0.04em; line-height: 1.3;
    }
    .intro-video__points strong {
      font-family: var(--font-jp-serif); font-weight: 500;
      font-size: 15px; letter-spacing: 0.06em;
      color: var(--primary); display: block; margin-bottom: 4px;
    }
    .intro-video__points div {
      font-size: 13.5px; line-height: 1.85;
      color: var(--ink-sub); letter-spacing: 0.04em;
    }
    .intro-video__note {
      font-size: 11.5px; color: var(--ink-muted);
      letter-spacing: 0.04em; line-height: 1.7;
      margin: 0;
    }
    @media (max-width: 768px) {
      #intro-video { padding: 64px 0; }
      .intro-video { grid-template-columns: 1fr; gap: 34px; max-width: 380px; }
      .intro-video__frame { max-width: min(82vw, 300px); margin: 0 auto; }
      .intro-video__points li { grid-template-columns: 30px 1fr; gap: 12px; }
      .intro-video__no { font-size: 16px; }
    }

    /* Design Samples */
    #design-samples {
      background: var(--paper-warm);
      border-top: 1px solid var(--line);
      border-bottom: 1px solid var(--line);
    }
    .sample-gallery {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 22px;
      align-items: stretch;
      max-width: 1280px;
      margin: 0 auto;
    }
    .sample-card,
    .sample-card--soon {
      display: flex;
      flex-direction: column;
      min-height: 100%;
      padding: 18px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: #fff;
      box-shadow: 0 16px 34px rgba(15, 23, 42, 0.07);
