    .nordic-list i {
      display: block;
      height: 25px;
      background: rgba(255, 252, 245, 0.82);
    }
    .sample-phone .nordic-page {
      height: calc(100% - 16px);
      padding: 8px;
    }
    .sample-phone .nordic-topline {
      grid-template-columns: 28px 1fr;
      margin-bottom: 9px;
    }
    .sample-phone .nordic-topline i:last-child { display: none; }
    .sample-phone .nordic-hero {
      grid-template-columns: 1fr;
      gap: 7px;
    }
    .sample-phone .nordic-image { height: 52px; }
    .sample-phone .nordic-list i { height: 18px; }
    .sample-tag {
      width: fit-content;
      padding: 5px 12px;
      border-radius: 999px;
      background: rgba(37, 99, 235, 0.09);
      color: var(--primary);
      font-family: var(--num-data);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 12px;
    }
    .sample-card h3,
    .sample-card--soon h3 {
      font-family: var(--serif);
      font-size: 19px;
      line-height: 1.65;
      margin: 0 0 10px;
      color: var(--ink);
    }
    .sample-card p,
    .sample-card--soon p {
      color: var(--ink-sub);
      font-size: 13.5px;
      line-height: 1.9;
      margin: 0 0 18px;
    }
    .sample-link {
      margin-top: auto;
      color: var(--primary);
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.05em;
    }
    .sample-card--soon {
      justify-content: center;
      background: rgba(255, 255, 255, 0.56);
      box-shadow: none;
    }
    .sample-card--soon .sample-preview {
      min-height: 132px;
      display: grid;
      place-items: center;
      color: #94a3b8;
      font-family: var(--num-data);
      font-size: 12px;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      border: 1px dashed rgba(148, 163, 184, 0.6);
      background: transparent;
    }
    .sample-note {
      max-width: 720px;
      margin: 28px auto 0 !important;
      color: var(--ink-sub);
      font-size: 12.5px;
      line-height: 1.85;
      text-align: center;
    }
    .sample-diagnostic-bridge {
      max-width: 860px;
      margin: 34px auto 0;
      padding: 26px 30px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 24px;
      align-items: center;
      border: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.76);
    }
    .sample-diagnostic-bridge__label {
      display: block;
      margin-bottom: 8px;
      color: var(--primary);
      font-family: var(--num-data);
      font-size: 11px;
      letter-spacing: 0.22em;
      text-transform: uppercase;
    }
    .sample-diagnostic-bridge h3 {
      margin: 0 0 8px;
      font-family: var(--serif);
      font-size: clamp(21px, 2.2vw, 28px);
      font-weight: 500;
      line-height: 1.45;
      letter-spacing: 0.06em;
      color: var(--ink);
    }
    .sample-diagnostic-bridge p {
      margin: 0 !important;
      color: var(--ink-sub);
      font-size: 13.5px !important;
      line-height: 1.85 !important;
      letter-spacing: 0.04em;
    }
    .sample-diagnostic-bridge__link {
      white-space: nowrap;
      color: var(--primary);
      font-weight: 600;
      font-size: 13px;
      letter-spacing: 0.08em;
    }
    @media (max-width: 768px) {
      .sample-gallery { grid-template-columns: 1fr; gap: 16px; }
      .sample-card, .sample-card--soon { padding: 14px; }
      .sample-preview { min-height: 230px; }
      .sample-browser { left: 14px; top: 24px; width: 74%; height: 166px; }
      .sample-phone { right: 12px; bottom: 14px; width: 78px; height: 152px; }
      .sample-preview--screen .sample-browser { left: 14px; top: 18px; width: 84%; height: 170px; }
      .sample-preview--screen .sample-phone { right: 12px; bottom: 14px; width: 78px; height: 154px; }
      .sample-diagnostic-bridge {
        grid-template-columns: 1fr;
        padding: 22px 20px;
        gap: 16px;
      }
      .sample-diagnostic-bridge__link { white-space: normal; }
      .sample-note { text-align: left; }
    }
    @media (min-width: 769px) and (max-width: 1120px) {
      .sample-gallery { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    /* Compliance */
    .compliance-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 28px;
      max-width: 920px; margin: 0 auto;
    }
    .compliance-card {
      padding: 36px 32px; border: 1px solid var(--line); background: var(--paper);
    }
    .compliance-card__cat {
      font-family: var(--num-deco); font-size: 11px; color: var(--gold);
      letter-spacing: 0.3em; text-transform: uppercase; margin-bottom: 10px;
    }
    .compliance-card__heading {
      font-family: var(--serif); font-weight: 500; font-size: 17px;
      margin: 0 0 20px; color: var(--primary); line-height: 1.55;
    }
    .compliance-list { list-style: none; padding: 0; margin: 0; }
    .compliance-list li {
      padding: 14px 0 14px 24px; border-bottom: 1px solid var(--line-soft);
      font-size: 14px; line-height: 1.7; position: relative; color: var(--ink);
    }
    .compliance-list li:last-child { border-bottom: none; }
    .compliance-list li::before {
      content: ""; position: absolute; left: 0; top: 25px;
      width: 12px; height: 1px; background: var(--gold);
    }
    .compliance-list li small {
      display: block; font-size: 12px; color: var(--ink-sub);
      letter-spacing: 0.04em; margin-top: 4px;
    }
    .compliance-statement {
      max-width: 720px; margin: 56px auto 0; padding: 40px 32px;
      background: var(--gold-soft); text-align: center;
    }
    .compliance-statement__quote {
      font-family: var(--serif); font-size: clamp(16px, 2vw, 19px);
      line-height: 2.0; color: var(--primary); margin: 0;
      letter-spacing: 0.03em;
    }
    .compliance-statement__sign {
      margin-top: 20px; font-family: var(--serif); font-size: 14px;
      color: var(--ink); letter-spacing: 0.1em;
    }
    .compliance-statement__sign small {
      display: block; font-family: var(--num-deco); font-size: 11px;
      color: var(--gold); letter-spacing: 0.2em; margin-top: 4px;
    }
    .compliance-note {
      max-width: 720px; margin: 32px auto 0;
      text-align: center; font-size: 13px; color: var(--ink-sub);
      line-height: 1.85;
    }
    .audit-box {
      max-width: 920px; margin: 48px auto 0;
      padding: 34px 36px; border: 1px solid var(--line);
      background: linear-gradient(180deg, #fff 0%, var(--paper-warm) 100%);
    }
    .audit-box__label {
      font-family: var(--num-deco); font-size: 11px; color: var(--gold);
      letter-spacing: 0.26em; text-transform: uppercase; margin-bottom: 10px;
    }
    .audit-box__heading {
      font-family: var(--serif); font-weight: 500;
      font-size: clamp(22px, 3vw, 30px); color: var(--primary);
      line-height: 1.65; margin: 0 0 14px;
    }
    .audit-box__lead {
      font-size: 14px; line-height: 2.0; color: var(--ink-sub);
      margin: 0 0 24px;
    }
    .audit-plans {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 14px; margin: 28px 0 22px;
    }
    .audit-plan {
      padding: 22px 20px; background: var(--paper);
      border: 1px solid var(--line-soft);
    }
    .audit-plan__name {
      font-family: var(--serif); color: var(--primary);
      font-size: 16px; line-height: 1.6; margin: 0 0 12px;
    }
    .audit-plan__price {
      font-family: var(--num-data); font-weight: 700;
      font-size: 28px; color: var(--primary-deep);
      line-height: 1; margin: 0 0 12px;
      font-variant-numeric: tabular-nums;
    }
    .audit-plan__price small {
      font-family: var(--sans); font-size: 0.45em;
      font-weight: 500; margin-left: 3px;
    }
    .audit-plan__text {
      font-size: 12.5px; line-height: 1.8;
      color: var(--ink-sub); margin: 0;
    }
    .audit-box__note {
      font-size: 12px; line-height: 1.8;
      color: var(--ink-muted); margin: 0;
    }
    @media (max-width: 768px) {
      .compliance-grid { grid-template-columns: 1fr; gap: 16px; }
      .compliance-card { padding: 28px 20px; }
      .compliance-statement { padding: 28px 18px; }
      .audit-box { padding: 28px 20px; }
      .audit-plans { grid-template-columns: 1fr; }
    }

    /* FAQ */
    .faq-wrap { max-width: 820px; margin: 0 auto; }
    .faq-item { border-bottom: 1px solid var(--line); }
    .faq-item:first-child { border-top: 1px solid var(--line); }
    .faq-q {
      cursor: pointer; padding: 24px 40px 24px 52px;
      font-family: var(--sans); font-weight: 500; font-size: 15px;
      color: var(--ink); list-style: none; position: relative;
      line-height: 1.7; transition: color 0.2s ease;
    }
    .faq-q::-webkit-details-marker { display: none; }
    .faq-q::before {
      content: "Q."; position: absolute; left: 14px; top: 24px;
      font-family: var(--num-deco); font-weight: 500; color: var(--gold);
      font-size: 17px; letter-spacing: 0.05em;
    }
    .faq-q::after {
      content: "+"; position: absolute; right: 14px; top: 21px;
      font-family: var(--num-deco); font-size: 24px; color: var(--gold); font-weight: 300;
    }
    .faq-item[open] .faq-q::after { content: "−"; }
    .faq-item:hover .faq-q { color: var(--primary); }
    .faq-a { padding: 0 52px 28px 52px; font-size: 14px; color: var(--ink-sub); line-height: 1.95; }
    .faq-a::before {
      content: "A."; display: inline-block; font-family: var(--num-deco);
      font-weight: 500; color: var(--primary); font-size: 15px;
      margin-right: 12px; letter-spacing: 0.05em;
    }
    @media (max-width: 768px) {
      .faq-q { padding: 20px 32px 20px 40px; font-size: 14px; }
      .faq-q::before { left: 10px; top: 22px; font-size: 15px; }
      .faq-q::after { right: 10px; top: 19px; }
      .faq-a { padding: 0 40px 24px 40px; font-size: 13px; }
    }

    /* Final CTA */
    .final-cta { background: var(--paper-warm); padding: 120px 0; text-align: center; border-top: 1px solid var(--line); }
    .final-cta .preface {
      font-size: 12px; color: var(--gold); letter-spacing: 0.25em;
      text-transform: uppercase; margin-bottom: 28px; font-family: var(--num-deco);
    }
    .final-cta h2 { font-size: clamp(26px, 3.4vw, 36px); margin-bottom: 28px; }
    .final-cta p { max-width: 580px; margin: 0 auto 40px; font-size: 15px; color: var(--ink-sub); line-height: 2.0; }
    .signature { margin-top: 64px; font-family: var(--serif); font-size: 17px; letter-spacing: 0.2em; color: var(--primary); }
    .signature small {
      display: block; font-family: var(--num-deco); font-size: 11px;
      color: var(--gold); letter-spacing: 0.25em; margin-bottom: 6px;
    }
    @media (max-width: 768px) {
      body { letter-spacing: 0.01em; }
      .chapter-head { margin-bottom: 38px; }
      .section-title {
        font-size: clamp(24px, 7vw, 30px);
        line-height: 1.6;
        letter-spacing: 0;
        text-wrap: balance;
      }
      .section-lead {
        max-width: 330px;
        font-size: 13px;
        line-height: 1.9;
        letter-spacing: 0.01em;
      }
      .final-cta { padding: 72px 0; text-align: left; }
      .final-cta .preface { text-align: center; letter-spacing: 0.18em; }
      .final-cta h2 {
        max-width: 330px;
        margin: 0 auto 20px;
        font-size: clamp(25px, 7vw, 29px);
        line-height: 1.65;
        letter-spacing: 0;
        text-align: left;
      }
      .final-cta p {
        max-width: 330px;
        margin: 0 auto 30px;
        font-size: 13.5px;
        line-height: 1.95;
        letter-spacing: 0.01em;
        text-align: left;
      }
      .consult-flow__head strong {
        font-size: 18px;
        line-height: 1.65;
        letter-spacing: 0;
      }
    }

    /* Footer */
    .footer { padding: 48px 0 56px; background: var(--paper); border-top: 1px solid var(--line); color: var(--ink-sub); font-size: 12px; letter-spacing: 0.05em; }
    .footer .wrap { display: flex; justify-content: space-between; align-items: center; gap: 20px; flex-wrap: wrap; }
    .footer .en { font-family: var(--num-deco); font-size: 11px; color: var(--gold); letter-spacing: 0.3em; text-transform: uppercase; }

    @media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

    /* === 2026 Vision-style refresh overrides === */
    :root {
      --paper: #f5f7fb;
      --paper-warm: #ffffff;
      --ink: #0f172a;
      --ink-sub: #475569;
      --primary: #2563eb;
      --primary-deep: #1d4ed8;
      --gold: #60a5fa;
      --line: rgba(148, 163, 184, 0.35);
      --line-soft: rgba(226, 232, 240, 0.7);
    }
    body {
      background: radial-gradient(1200px 700px at 50% -10%, rgba(147,197,253,.35), transparent 65%), var(--paper);
      color: var(--ink);
    }
    .topbar {
      background: rgba(248, 250, 252, 0.72);
      border-bottom: 1px solid rgba(148,163,184,.28);
      backdrop-filter: saturate(180%) blur(22px);
      -webkit-backdrop-filter: saturate(180%) blur(22px);
    }
    .footer-brand {
      display: grid;
      gap: 10px;
      max-width: 430px;
    }
    .footer-logo {
      display: block;
      width: 150px;
      height: auto;
      mix-blend-mode: multiply;
    }
    .nav-cta, .cta, .button, button[type="submit"] {
      border-radius: 999px !important;
      box-shadow: 0 10px 28px rgba(37,99,235,.24);
    }
    .hero { padding: 0 0 92px; }
    .hero-showcase,
    .hero-path,
    .hero-card,
    .card,
    .point-card,
    .price-card,
    .flow-card,
    .faq-item,
    .panel,
    .voice,
    .contact-box,
    .contact-card {
      border-radius: 24px !important;
      border: 1px solid rgba(148,163,184,.26) !important;
      background: rgba(255,255,255,.76) !important;
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      box-shadow: 0 14px 40px rgba(15,23,42,.08);
    }
    .hero-path__photo,
    .hero-showcase,
    .visual img,
    .card img,
    .point-card img,
    .scene img,
    .gallery img {
      border-radius: 20px;
    }
    .hero .hero-showcase {
      width: 100vw;
      max-width: none;
      height: clamp(360px, 46vw, 760px);
      aspect-ratio: auto;
      margin: 0 calc(50% - 50vw) 48px;
      border-left: 0 !important;
      border-right: 0 !important;
      border-radius: 0 !important;
      box-shadow: none;
      background: #eef3f6 !important;
    }
    .hero .hero-showcase video {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .hero .hero-showcase__slide:nth-child(1) img,
    .hero .hero-showcase__slide:nth-child(1) video { object-position: center 44%; }
    .hero .hero-showcase__slide:nth-child(2) img,
    .hero .hero-showcase__slide:nth-child(2) video { object-position: center 46%; }
    .hero .hero-showcase__slide:nth-child(3) img,
    .hero .hero-showcase__slide:nth-child(3) video { object-position: center 44%; }
    .chapter-num { letter-spacing: .22em; font-family: var(--num-data); }
    h1,h2,h3 { letter-spacing: .01em; }
    section { padding: 110px 0; }
    .section-lead { color: #64748b; }
    @media (max-width: 768px){
      section { padding: 74px 0; }
      .hero { padding: 0 0 64px; }
      .hero .hero-showcase {
        height: clamp(240px, 68vw, 360px);
        margin-bottom: 32px;
      }
      .hero .hero-showcase__slide:nth-child(1) img,
      .hero .hero-showcase__slide:nth-child(1) video { object-position: 52% center; }
      .hero .hero-showcase__slide:nth-child(2) img,
      .hero .hero-showcase__slide:nth-child(2) video { object-position: 46% center; }
      .hero .hero-showcase__slide:nth-child(3) img,
      .hero .hero-showcase__slide:nth-child(3) video { object-position: center; }
    }



    /* Split-page home shortcuts */
    .home-shortcuts {
      background: #f5f5f7;
      border-top: 1px solid var(--line);
      border-bottom: 1px solid var(--line);
    }
    .home-shortcuts__grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 16px;
      margin-top: 34px;
    }
    .home-shortcut {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 132px;
      gap: 18px;
      align-items: center;
      min-height: 164px;
      padding: 22px;
      color: var(--ink);
      text-decoration: none;
      background: rgba(255,255,255,0.92);
      border: 1px solid rgba(31,77,107,0.08);
      border-radius: 24px;
      box-shadow: 0 18px 46px rgba(21, 40, 52, 0.06);
      transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
    }
    .home-shortcut:hover {
      transform: translateY(-4px);
      border-color: rgba(31,77,107,0.18);
      box-shadow: 0 24px 60px rgba(21, 40, 52, 0.10);
    }
    .home-shortcut__num {
      display: inline-block;
      margin-bottom: 10px;
      font-family: var(--num);
      font-size: 12px;
      letter-spacing: .18em;
      color: var(--primary);
    }
    .home-shortcut__icon {
      width: 58px;
      height: 58px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      margin: 0 0 18px;
      border-radius: 18px;
      background: #f2f5f7;
      color: var(--primary);
    }
    .home-shortcut__icon svg {
      width: 30px;
      height: 30px;
      stroke: currentColor;
    }
    .home-shortcut h3 {
      margin: 0 0 10px;
      font-size: 22px;
      line-height: 1.45;
      letter-spacing: 0;
    }
    .home-shortcut p {
      margin: 0;
      color: var(--ink-sub);
      font-size: 14px;
      line-height: 1.75;
    }
    .home-shortcut__link {
      display: inline-block;
      margin-top: 16px;
      color: var(--primary);
      font-size: 13px;
      font-weight: 700;
      letter-spacing: .04em;
    }
    .home-shortcut__photo {
      width: 100%;
      aspect-ratio: 4 / 3;
      margin: 0;
      overflow: hidden;
      border-radius: 18px;
      background: #eef3f6;
    }
    .home-shortcut__photo img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }
    .home-shortcut--wide {
      grid-column: span 2;
    }
    @media (max-width: 860px) {
      .home-shortcuts__grid {
        grid-template-columns: 1fr;
        gap: 12px;
      }
      .home-shortcut,
      .home-shortcut--wide {
        grid-column: auto;
      }
    }
    @media (max-width: 640px) {
      .home-shortcut {
        grid-template-columns: minmax(0, 1fr) 96px;
        min-height: 132px;
        padding: 16px;
        border-radius: 18px;
      }
      .home-shortcut__icon {
        display: none;
      }
      .home-shortcut h3 {
        font-size: 18px;
        margin-bottom: 6px;
      }
      .home-shortcut p {
        font-size: 12px;
        line-height: 1.65;
      }
      .home-shortcut__link {
        margin-top: 10px;
        font-size: 12px;
      }
      .home-shortcut__photo {
        border-radius: 14px;
      }
    }

    /* Impression feature collection */
    .impression-features {
      background:
        radial-gradient(circle at 12% 0%, rgba(244, 188, 190, .26), transparent 34%),
        radial-gradient(circle at 92% 18%, rgba(212, 175, 55, .16), transparent 30%),
        linear-gradient(180deg, #fffaf7 0%, #f7f9fc 100%);
      border-top: 1px solid var(--line);
      border-bottom: 1px solid var(--line);
    }
    .impression-features__grid {
      display: grid;
      grid-template-columns: minmax(300px, .92fr) minmax(0, 1.08fr);
      gap: 38px;
      align-items: center;
      margin-top: 36px;
    }
    .impression-features__visual {
      position: relative;
      margin: 0;
      overflow: hidden;
      border-radius: 30px;
      border: 1px solid rgba(180, 140, 70, .22);
      background: #fff;
      box-shadow: 0 28px 70px rgba(142, 104, 75, .14);
    }
    .impression-features__visual img,
    .impression-features__visual video {
      display: block;
      width: 100%;
      height: auto;
    }
    .impression-features__visual video {
      aspect-ratio: 9 / 16;
      object-fit: cover;
      background: #f7f2ed;
    }
    .impression-features__badge {
      position: absolute;
      left: 22px;
      bottom: 22px;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 10px 14px;
      border-radius: 999px;
      color: #7a4d55;
      background: rgba(255, 255, 255, .78);
      border: 1px solid rgba(192, 132, 132, .24);
      backdrop-filter: blur(14px);
      font-size: 12px;
      font-weight: 700;
      letter-spacing: .08em;
    }
    .impression-features__copy {
      max-width: 680px;
    }
    .impression-features__copy h3 {
      margin: 0 0 18px;
      font-size: clamp(26px, 3.2vw, 40px);
      line-height: 1.48;
      letter-spacing: .01em;
    }
    .impression-features__copy p {
      margin: 0;
      color: var(--ink-sub);
      line-height: 2;
      font-size: 15px;
    }
    .impression-features__list {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
      margin-top: 28px;
    }
    .impression-feature {
      min-height: 276px;
