      border: 1px solid rgba(148, 163, 184, .22);
      box-shadow: 0 16px 42px rgba(30, 41, 59, .06);
    }
    .impression-feature--wide {
      grid-column: 1 / -1;
    }
    .impression-feature__demo {
      position: relative;
      height: 104px;
      margin-bottom: 14px;
      overflow: hidden;
      border-radius: 18px;
      background: linear-gradient(135deg, #fbfaf7 0%, #edf5f8 100%);
      border: 1px solid rgba(148, 163, 184, .18);
    }
    .impression-demo--splash {
      background:
        radial-gradient(circle at 78% 18%, rgba(212,175,55,.22), transparent 32%),
        linear-gradient(135deg, #fffaf7 0%, #f3f7fa 100%);
