    .impression-demo--splash img {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .impression-demo--splash .splash-demo__photo {
      opacity: 0;
      transform: scale(1.05);
      filter: saturate(.98) brightness(1.04);
      animation: splashPhotoReveal 4.8s ease-in-out infinite;
    }
    .impression-demo--splash .splash-demo__logo {
      top: 50%;
      left: 50%;
      right: auto;
      bottom: auto;
      width: 118px;
      height: auto;
      object-fit: contain;
      transform: translate(-50%, -50%);
      opacity: .94;
      filter: drop-shadow(0 10px 18px rgba(181,138,66,.18));
      animation: splashLogoReveal 4.8s ease-in-out infinite;
      z-index: 2;
    }
    .impression-demo--splash .splash-demo__veil {
      position: absolute;
      inset: 0;
      background: linear-gradient(90deg, rgba(255,255,255,.86), rgba(255,255,255,.16));
      opacity: 0;
      animation: splashVeilReveal 4.8s ease-in-out infinite;
      z-index: 1;
    }
    .impression-demo--splash .splash-demo__label {
      position: absolute;
      left: 12px;
      bottom: 10px;
      z-index: 3;
      padding: 5px 9px;
      border-radius: 999px;
      color: #fff;
      background: rgba(15, 23, 42, .48);
      font-family: var(--num-data);
      font-size: 9px;
      letter-spacing: .18em;
      text-transform: uppercase;
      opacity: 0;
      animation: splashLabelReveal 4.8s ease-in-out infinite;
    }
    .impression-demo--splash::after {
      content: "";
      position: absolute;
      left: -35%;
      top: 0;
      width: 32%;
      height: 100%;
      transform: skewX(-18deg);
      background: linear-gradient(90deg, transparent, rgba(255,255,255,.9), transparent);
      animation: impressionSweep 2.7s ease-in-out infinite;
      z-index: 4;
    }
    @keyframes splashLogoReveal {
      0%, 36% { opacity: .94; transform: translate(-50%, -50%) scale(1); }
      54%, 100% { opacity: 0; transform: translate(-50%, -50%) scale(.94); }
    }
    @keyframes splashPhotoReveal {
      0%, 34% { opacity: 0; transform: scale(1.06); }
      52%, 86% { opacity: 1; transform: scale(1.01); }
      100% { opacity: 0; transform: scale(1); }
    }
    @keyframes splashVeilReveal {
      0%, 42% { opacity: 0; }
      56%, 86% { opacity: 1; }
      100% { opacity: 0; }
    }
    @keyframes splashLabelReveal {
      0%, 48% { opacity: 0; transform: translateY(4px); }
      60%, 86% { opacity: 1; transform: translateY(0); }
      100% { opacity: 0; transform: translateY(4px); }
    }
    @keyframes impressionSweep {
      0%, 24% { left: -35%; opacity: 0; }
      38% { opacity: 1; }
      72%, 100% { left: 108%; opacity: 0; }
    }
    .impression-demo--photo img {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: opacity .8s ease;
      animation: impressionPhotoFade 5.8s ease-in-out infinite;
