    .impression-demo--photo img:nth-child(2) { animation-delay: 2.9s; opacity: 0; }
    @keyframes impressionPhotoFade {
      0%, 44% { opacity: 1; transform: scale(1); }
      50%, 94% { opacity: 0; transform: scale(1.025); }
      100% { opacity: 1; transform: scale(1); }
    }
    .impression-demo--photo::after {
