/* ============================================================
 * 強制リフロー対策版（旧 scroll loop → IntersectionObserver）
 * - 旧コード: scroll毎に .data 全要素の offset/height/scrollTop を読み込み
 * - 新コード: ブラウザ最適化されたIntersectionObserverで非同期判定
 * ============================================================ */
(function() {
    'use strict';

    // .news の遅延読み込み（DOM準備後に実行）
    document.addEventListener('DOMContentLoaded', function() {
        var newsEl = document.querySelector('.news');
        if (newsEl && typeof jQuery !== 'undefined') {
            jQuery(newsEl).load('news/index.php');
        }
    });

    // .data 要素のアニメ発火 (旧 scrollハンドラを置換)
    if ('IntersectionObserver' in window) {
        var dataObserver = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                if (entry.isIntersecting) {
                    entry.target.classList.add('is-anim');
                    dataObserver.unobserve(entry.target); // 一度発火したら監視停止
                }
            });
        }, {
            rootMargin: '0px 0px -25% 0px', // 画面下から25%地点で発火（旧wh/4と同等）
            threshold: 0.01
        });
        document.querySelectorAll('.data').forEach(function(el) {
            dataObserver.observe(el);
        });
    } else {
        // フォールバック（古いブラウザ）: 即座に全要素にクラス付与
        document.querySelectorAll('.data').forEach(function(el) {
            el.classList.add('is-anim');
        });
    }

    // top-bnr 閉じるボタン
    document.addEventListener('click', function(e) {
        if (e.target.closest('.top-bnr__close')) {
            var tb = document.querySelector('.top-bnr');
            if (tb) tb.classList.toggle('is-close');
        }
    }, { passive: true });
})();



