/* contactform7 */
.wpcf7{
background: #fff;
border:none;
}

.contact-form table{
margin:0 auto;
}

.contact-form table input , .contact-form table textarea{
background-color: #f7f7f7;
}

.contact-form tr{
border-top:1px solid #ddd;
}

.contact-form tr:last-child{
border-bottom:1px solid #ddd;
}

.contact-form tr p{
margin:10px 0;
}

.contact-form th{
 text-align:left;
 width:30%;
 background:none;
}

.contact-form td{
width:570px;
}

.contact-form th,.contact-form td{
border: none;
}

.contact-form .required,.contact-form .any{
font-size: 12px;
padding: 2px 12px;
color: #fff;
margin: 0 0 0 10px;
position: relative;
bottom: 1px;
}
.contact-form .required{
background: #0059b2;
}

.contact-form .any{
background: #999;
}

.contact-form input[type="submit"]{
background:#0059b2;
color:#fff;
}

.contact-form input[type="submit"],.contact-form input[type="button"]{
font-size:18px;
border: none;
width: 300px;
height:50px;
display: block;
margin: 30px auto 0;
}

.contact-form input[type="submit"]:hover{
 background:#003366;
}

.contact-form .form-text{
text-align:center;
}

.contact-form .form-text p{
margin:1em 0;
font-size: 1.4em;
font-weight: bold;
}

.contact-form .wpcf7c-conf{
background-color: #bcc0c3;
}

@media(max-width:600px){
.wpcf7 form{
margin:0;
}
.contact-form th{
padding:17px 15px 0px;
}
.contact-form th, .contact-form td {
display:block;
width:100%;
}
.contact-form th p{
margin:0px;
}
.contact-form .wpcf7-submit{
font-size:17px;
}
}
