/* Hero KV: width/height 属性が無いため CLS 対策で aspect-ratio を固定 */
.hero-kv img{
	display:block;
	width:100%;
	height:auto;
	aspect-ratio:1536/1024;
	object-fit:cover;
}
/* Contact Form 7: 入力域は読みやすさ優先で 640px 程度に */
.wpcf7-form{
	max-width:640px;
	margin-left:auto;
	margin-right:auto;
}
/* コラム公開日表示 */
.column-meta{
	margin:0 0 1.25em;
	color:#666;
	font-size:.92em;
	line-height:1.6;
}
.column-meta time{
	font-variant-numeric:tabular-nums;
}
.column-meta-author{margin-right:.4em}

/* 本文内関連記事 */
.column-inline-related{
	margin:2em 0;
	padding:1em 1.25em;
	border-left:4px solid #e67d2b;
	background:#fff8ef;
	font-size:.95em;
	line-height:1.8;
}
.column-inline-related::before{
	display:block;
	margin-bottom:.35em;
	font-size:.82em;
	font-weight:600;
	letter-spacing:.05em;
	color:#c25f10;
	content:"関連記事";
}
.column-inline-related a{
	text-decoration:underline;
}

/* ハンバーガー × アニメーション */
.hamburger{
	position:relative;
}
.hamburger span{
	transition:transform .25s ease,opacity .2s ease,top .25s ease;
}
.hamburger.is-open span:nth-child(1){
	transform:translateY(7px) rotate(45deg);
}
.hamburger.is-open span:nth-child(2){
	opacity:0;
}
.hamburger.is-open span:nth-child(3){
	transform:translateY(-7px) rotate(-45deg);
}
/* SP本文の孤立改行対策 */
@media (max-width:768px){
	.hero-kv h1,.hero-kv h2,.hero-kv p,
	.section-title,.section-lead,
	.service-card li,
	.plan-card .plan-lead,
	.challenge-lead,
	.column-inline-related{
		word-break:auto-phrase;
		overflow-wrap:anywhere;
		line-break:strict;
	}
}


