*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --orange: #F5A623; --orange-dark: #E09410;
  --dark: #1A1A1A; --gray: #555;
  --light-gray: #F7F7F7; --border: #E5E5E5; --white: #fff;
  --green-dark: #1B4332; --green-mid: #2D6A4F; --green-light: #52B788;
}
html { scroll-behavior: smooth; }
body { font-family: 'Noto Sans JP', sans-serif; color: var(--dark); line-height: 1.7; font-size: 16px; }

/* COMMON */
.container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }
.section-label { display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--orange); margin-bottom: 12px; }
.section-title { font-size: clamp(24px, 3.5vw, 36px); font-weight: 900; line-height: 1.35; color: var(--dark); margin-bottom: 16px; word-break: keep-all; }
.section-desc { font-size: 15px; color: var(--gray); line-height: 1.85; max-width: 580px; }
.section-center { text-align: center; margin-bottom: 56px; }
.section-center .section-desc { margin: 0 auto; }
section { scroll-margin-top: 72px; }

/* HEADER */
#site-header { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; height: 72px; min-height: 72px; background: rgba(255,255,255,0.97); backdrop-filter: blur(10px); border-bottom: 1px solid rgba(0,0,0,0.07); box-shadow: 0 2px 12px rgba(0,0,0,0.06); display: flex; align-items: center; }
.header-inner { max-width: 1200px; margin: 0 auto; padding: 0 24px; width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 20px; height: 100%; }
.header-logo { display: flex; align-items: center; }
.header-logo img { height: 36px; width: auto; display: block; }
.header-nav { display: flex; align-items: center; gap: 32px; list-style: none; height: 100%; margin: 0 !important; padding-left: 0 !important; }
.header-nav a { text-decoration: none; color: var(--dark); font-size: 14px; font-weight: 500; transition: color 0.2s; display: flex; align-items: center; height: 100%; }
.header-nav a:hover { color: var(--orange); }
.header-actions { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.btn-header-sub { text-decoration: none; color: var(--dark); font-size: 13px; font-weight: 600; padding: 8px 16px; background: transparent; border: 1.5px solid rgba(26,26,26,0.28); border-radius: 6px; transition: all 0.2s; white-space: nowrap; line-height: 1; }
.btn-header-sub:hover { background: var(--dark); border-color: var(--dark); color: var(--white); }
.btn-header-main { text-decoration: none; background: var(--orange); color: var(--white); font-size: 13px; font-weight: 700; padding: 10px 22px; border-radius: 6px; white-space: nowrap; transition: background 0.2s; line-height: 1; }
.btn-header-main:hover { background: var(--orange-dark) !important; color: var(--white) !important; }
.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; background: none; border: none; padding: 4px; }
.hamburger span { display: block; width: 24px; height: 2px; background: var(--dark); }

/* MOBILE NAV */
.mobile-nav { display: none; position: fixed; top: 72px; left: 0; right: 0; background: var(--white); border-bottom: 1px solid var(--border); padding: 20px 24px; z-index: 999; flex-direction: column; gap: 0; }
.mobile-nav.open { display: flex; }
.mobile-nav > a { text-decoration: none; color: var(--dark); font-size: 15px; font-weight: 500; padding: 14px 0; border-bottom: 1px solid var(--border); }
.mobile-nav-actions { display: flex; gap: 10px; margin-top: 0; padding-top: 16px; border-top: 1px solid var(--border); margin-left: 0 !important; }
.mobile-nav-actions a { flex: 1; text-align: center; padding: 13px; border-radius: 6px; font-weight: 700; font-size: 14px; text-decoration: none; font-family: 'Noto Sans JP', sans-serif; }
.mnav-main { background: var(--orange); color: var(--white); }
.mnav-sub { background: var(--dark); color: var(--white); border: none; }
.mnav-main:hover { background: var(--orange-dark) !important; color: var(--white) !important; }
.mnav-sub:hover { background: #333 !important; color: var(--white) !important; }

/* FLOATING CTA */
.floating-cta { position: fixed; right: 20px; bottom: 32px; z-index: 900; display: flex; flex-direction: column; gap: 10px; }
.floating-btn { display: flex; flex-direction: column; align-items: center; justify-content: center; width: 70px; height: 70px; border-radius: 50%; text-decoration: none; font-size: 10px; font-weight: 700; line-height: 1.4; text-align: center; box-shadow: 0 4px 16px rgba(0,0,0,0.16); transition: transform 0.2s, box-shadow 0.2s; color: var(--white); }
.floating-btn:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,0.22); color: var(--white) !important; }
.f-contact { background: var(--orange); }
.f-dl { background: #666; }
.floating-btn svg { margin-bottom: 2px; }

/* MOBILE BOTTOM BAR */
.mobile-bottom-bar { display: none; position: fixed; bottom: 0; left: 0; right: 0; z-index: 900; background: var(--white); border-top: 1px solid var(--border); padding: 10px 16px; gap: 10px; }
.mobile-bottom-bar a { flex: 1; display: flex; align-items: center; justify-content: center; padding: 13px; border-radius: 4px; text-decoration: none; font-size: 13px; font-weight: 700; }
.mbb-contact { background: var(--orange); color: var(--white); }
.mbb-dl { background: #666; color: var(--white); }

/* BUTTONS */
.btn-primary { display: inline-flex; align-items: center; gap: 8px; background: var(--orange); color: var(--white); text-decoration: none; padding: 16px 32px; border-radius: 5px; font-weight: 700; font-size: 15px; transition: background 0.2s, transform 0.2s, box-shadow 0.2s; box-shadow: 0 4px 16px rgba(245,166,35,0.28); }
.btn-primary:hover { background: var(--orange-dark) !important; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(245,166,35,0.38); color: var(--white) !important; }
.btn-secondary { display: inline-flex; align-items: center; gap: 8px; background: #666; color: var(--white); text-decoration: none; padding: 16px 28px; border-radius: 5px; font-weight: 700; font-size: 15px; border: 1.5px solid #666; transition: background 0.2s, transform 0.2s; }
.btn-secondary:hover { background: #555; border-color: #555; transform: translateY(-2px); }

/* HERO */
#hero { padding-top: 0; min-height: 640px; display: flex; align-items: stretch; background: #faf8f4; position: relative; overflow: hidden; }
#hero::before { display: none; }
.hero-content { background: none; padding: 0; }
.hero-inner { display: flex; flex-direction: row; align-items: stretch; width: 100%; max-width: 100%; margin: 0; padding: 0; position: relative; text-align: left; }
.hero-content { flex: 0 0 42%; display: flex; flex-direction: column; justify-content: center; padding: 80px 48px 80px 64px; position: relative; z-index: 2; background: linear-gradient(to right, #faf8f4 82%, rgba(250,248,244,0) 100%); }
.hero-eyebrow { display: inline-flex; align-items: center; gap: 6px; background: rgba(245,166,35,0.12); border: 1px solid rgba(245,166,35,0.32); padding: 5px 16px; border-radius: 100px; font-size: 11px; font-weight: 700; color: var(--orange-dark); margin-bottom: 20px; align-self: flex-start; white-space: nowrap; letter-spacing: 0.04em; }
.hero-title { font-size: clamp(24px, 3.2vw, 44px); font-weight: 900; line-height: 1.3; color: var(--dark); margin-bottom: 20px; word-break: keep-all; letter-spacing: -0.01em; text-shadow: 0 0 28px rgba(250,248,244,1), 0 0 56px rgba(250,248,244,0.9); }
.hero-title em { font-style: normal; color: var(--orange); text-shadow: 0 0 24px rgba(250,248,244,1), 0 0 48px rgba(250,248,244,0.8); }
.hero-desc { font-size: 14px; color: var(--gray); line-height: 1.9; margin-bottom: 32px; max-width: 420px; }
.hero-btns { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-visual { display: none; }
.hero-kv { position: absolute; right: 0; top: 0; width: 60%; height: 100%; }
.hero-kv::before { content: ''; position: absolute; left: 0; top: 0; width: 80px; height: 100%; background: linear-gradient(to right, #faf8f4, rgba(250,248,244,0)); z-index: 1; pointer-events: none; }
.hero-kv img { width: 100%; height: 100%; object-fit: cover; object-position: center top; display: block; }

/* PROBLEMS */
#problems { padding: 96px 0; background: #F7F7F7; }
#problems .section-title { color: var(--dark); }
#problems .section-desc { color: var(--gray); }
.problems-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.problem-list { text-align: left; }
.problem-card { background: var(--white); border: 1px solid var(--border); border-radius: 12px; padding: 28px 28px 32px; }
.problem-card-title { font-size: 14px; font-weight: 700; color: var(--orange); margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid var(--border); }
.problem-list { list-style: none; display: flex; flex-direction: column; gap: 9px; }
.problem-list li { font-size: 13px; color: var(--gray); display: flex; align-items: flex-start; gap: 8px; line-height: 1.65; }
.problem-list li::before { content: '・'; color: var(--orange); flex-shrink: 0; }

/* ABOUT */
#about { padding: 96px 0; background: var(--white); }
.about-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; max-width: 900px; margin: 0 auto; }
.about-card { background: var(--light-gray); border-radius: 12px; padding: 32px 24px; border: 1px solid var(--border); transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s; }
.about-card:hover { border-color: var(--orange); box-shadow: 0 6px 24px rgba(245,166,35,0.10); transform: translateY(-3px); }
.about-card-icon { width: 50px; height: 50px; background: rgba(245,166,35,0.12); border-radius: 12px; display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; }
