.about-card-desc { font-size: 13px; color: var(--gray); line-height: 1.75; }

/* SERVICES */
#services { padding: 96px 0; background: var(--light-gray); }
.services-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; }
.service-card { background: var(--white); border-radius: 12px; padding: 30px 22px; text-align: center; border: 1px solid var(--border); transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s; display: flex; flex-direction: column; align-items: center; }
.service-card:hover { border-color: var(--orange); box-shadow: 0 8px 28px rgba(245,166,35,0.11); transform: translateY(-4px); }
.service-icon { width: 60px; height: 60px; background: rgba(245,166,35,0.12); border-radius: 14px; display: flex; align-items: center; justify-content: center; margin: 0 auto 18px; }
.service-title { font-size: 14px; font-weight: 700; color: var(--dark); margin-bottom: 14px; }
.service-list { list-style: none; text-align: left; display: flex; flex-direction: column; gap: 7px; width: 100%; }
.service-list li { font-size: 12px; color: var(--gray); display: flex; align-items: flex-start; gap: 6px; line-height: 1.55; text-align: left; }
.service-list li::before { content: '✓'; color: var(--orange); flex-shrink: 0; font-weight: 700; min-width: 12px; }

/* REASON */
#reason { padding: 96px 0; background: var(--white); }
.reason-table { width: 100%; border-collapse: collapse; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
.reason-table th { padding: 18px 22px; font-size: 13px; font-weight: 700; text-align: center; }
.reason-table th:first-child { background: var(--light-gray); color: var(--gray); text-align: left; width: 28%; }
.reason-table th:nth-child(2) { background: #EEE; color: var(--gray); width: 36%; }
.reason-table th:nth-child(3) { background: var(--orange); color: var(--white); width: 36%; }
.reason-table td { padding: 16px 22px; font-size: 13px; border-top: 1px solid var(--border); }
.reason-table td:first-child { font-weight: 700; color: var(--dark); background: var(--light-gray); }
.reason-table td:nth-child(2) { color: var(--gray); text-align: center; }
.reason-table td:nth-child(3) { color: var(--orange-dark); font-weight: 700; text-align: center; background: rgba(245,166,35,0.04); }

/* WORKS */
#works { padding: 96px 0; background: var(--light-gray); }
.works-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; margin-bottom: 44px; }
.work-card { background: var(--white); border-radius: 12px; overflow: hidden; box-shadow: 0 3px 14px rgba(0,0,0,0.07); transition: transform 0.2s, box-shadow 0.2s; }
