.work-visual-2 { background: linear-gradient(135deg, #1a3a5c 0%, #2e6da4 60%, #5ba3d9 100%); }
.work-visual-3 { background: linear-gradient(135deg, #5c3a00 0%, #a06200 60%, #F5A623 100%); }
.work-visual-label { position: absolute; top: 14px; left: 14px; background: rgba(255,255,255,0.18); color: white; font-size: 10px; font-weight: 700; padding: 3px 10px; border-radius: 100px; letter-spacing: 0.04em; }
.work-visual-title { font-size: 15px; font-weight: 900; color: white; line-height: 1.4; text-shadow: 0 1px 4px rgba(0,0,0,0.3); }
.work-body { padding: 22px; }
.work-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; } .work-tag { background: rgba(245,166,35,0.12); color: var(--orange-dark); font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 20px; display: inline-block; } .work-card-link { color: #666; display: inline-flex; align-items: center; gap: 5px; font-weight: 600; font-size: 12px; text-decoration: none; }
.work-title { font-size: 14px; font-weight: 700; color: var(--dark); margin-bottom: 6px; }
